window.T7 = window.T7 || [];
T7.push(
{id:"m1",n:"1-mavzu",t:"Inson – ezgulik ijodkori",b:1,
 map:{c:"Inson – ezgulik ijodkori",br:[
  {t:"Bunyodkorlik",e:"🏛️",k:["Yuliy Sezar","Amir Temur","imoratlar"],x:"Inson shaharlar, bog‘lar va inshootlar yaratadi. Amir Temur: «Qudratimizga shubha qilsangiz, biz qurgan imoratlarga boqing»."},
  {t:"Vatanga qaytish",e:"✈️",k:["sayohat","uy zavqi","Vatan bo‘lagi"],x:"Sayohat qilish, dunyo ko‘rish yaxshi, ammo Vatanga qaytishning gashti o‘zgacha. Inson Vatanning aziz bir bo‘lagi."},
  {t:"Vatan sog‘inchi",e:"💌",k:["Bahodir","Andijon","ota duosi"],x:"Nosir Zohid hikoyasida Amerikada tug‘ilgan Bahodirning otasi Vatanda vafot etishni orzu qilgan va duosi ijobat bo‘lgan."},
  {t:"Vatan tuyg‘usi",e:"❤️",k:["Abdulla Avloniy","arab, eskimo","cho‘pon bo‘l"],x:"Avloniy: har bir xalq o‘z vatanini boshqa yerlardan ziyoda suyadi. «Kishi yurtida sulton bo‘lguncha, o‘z yurtingda cho‘pon bo‘l»."},
  {t:"Yurtga mas’ullik",e:"📜",k:["49-modda","meros","yaxshi odam"],x:"Konstitutsiyaning 49-moddasi bo‘yicha fuqarolar tarixiy, ma’naviy va madaniy merosni avaylab-asrashi kerak. Amir Temur: «Yaxshi odam yurt tuzar, yomon odam yurt buzar»."}]},
 q:[
 {t:"m",q:"«Qudratimizga shubha qilsangiz, biz qurgan imoratlarga boqing» – bu kimning fikri?",a:["Amir Temur","Yuliy Sezar","Abdulla Avloniy","Mirzo Bobur"],e:"Darslikda bu so‘zlar Amir Temurniki sifatida keltirilgan va «Inson – ezgulik ijodkori» fikri bilan bog‘lanadi."},
 {t:"m",q:"«Men ko‘rgan Rim paxsa devorli edi, men qoldirayotgan Rim go‘zal imoratlardir» deb kim aytgan?",a:["Yuliy Sezar","Amir Temur","Konfutsiy","Arastu"],e:"Yuliy Sezarning bu fikri inson bunyodkorligiga misol qilib berilgan."},
 {t:"m",q:"«Vatandin yaxshi yor bo‘lmas...» hikoyasidagi Bahodir qaysi kasb bilan shug‘ullanadi?",a:["Qandolatchilik","Duradgorlik","Kulolchilik","Zargarlik"],e:"Bahodir Amerikada o‘sgan va ota-buvalaridan meros kasb – qandolatchilik bilan shug‘ullanadi."},
 {t:"m",q:"Bahodirning ota-bobosi asli qayerdan edi?",a:["Andijondan","Samarqanddan","Namangandan","Buxorodan"],e:"Bahodir ota-bobosi asli andijonlik ekanini aytadi; otasi Andijon odamlari va Bog‘ishamol haqida ko‘p gapirgan."},
 {t:"m",q:"Bahodirning otasi O‘zbekistonni eslaganda qanday duo qilardi?",a:["Vatanida ko‘z yumish nasib etishini","Farzandi katta boylik orttirishini","Amerikada uzoq umr ko‘rishni","Yangi qandolat do‘koni ochishni"],e:"U «Vatanimda ko‘z yumish nasib etsin» deb duo qilar edi va duosi ijobat bo‘ldi."},
 {t:"m",q:"Abdulla Avloniy xalqlarning o‘z vatanini suyishiga qaysi misolni keltiradi?",a:["Eskimular sovuq qor va muzlik yerlarini suyadi","Savdogarlar faqat boy va gavjum shaharlarni suyadi","Sayyohlar faqat issiq o‘lkalarni suyadi","Dehqonlar faqat unumdor yerlarni suyadi"],e:"Avloniy: arablar issiq cho‘llarini, eskimular sovuq muzlik yerlarini boshqa yerlardan ziyoda suyadi."},
 {t:"m",q:"Bobolar hikmatiga ko‘ra, kishi yurtida sulton bo‘lgandan nima afzal?",a:["O‘z yurtingda cho‘pon bo‘lish","Uzoq yurtda savdogar bo‘lish","Begona shaharda olim bo‘lish","Dunyo kezib sayyoh bo‘lish"],e:"«Kishi yurtida sulton bo‘lguncha, o‘z yurtingda cho‘pon bo‘l» – Vatan qadri haqidagi hikmat."},
 {t:"m",q:"Darslikka ko‘ra, intellektual salohiyat qachon yuksak natija beradi?",a:["Vatanga muhabbat bilan uyg‘unlashganda","Katta mukofot va’da qilinganda","Kimdir majburlab, nazorat qilib ishlatganda","Chet elda tan olingandagina"],e:"Intellektual salohiyat Vatanga muhabbat tuyg‘usi bilan uyg‘un bo‘lgandagina yuksak natija beradi."},
 {t:"tf",q:"«Yaxshi odam yurt tuzar, yomon odam yurt buzar» – Amir Temur hikmati.",a:true,e:"Bu hikmat «Ma’naviyat xazinasidan» ruknida Amir Temur nomidan berilgan."},
 {t:"tf",q:"Mavzudagi maslahatga ko‘ra, dunyo ko‘rgan inson Vatanga qaytmasligi kerak.",a:false,e:"Aksincha: sayohat qiling, o‘qib-o‘rganing va bir kuni, albatta, Vatanga qayting."},
 {t:"tf",q:"Konstitutsiyaning 49-moddasiga oid topshiriq tarixiy va madaniy merosni asrash majburiyati haqida.",a:true,e:"Topshiriqda fuqarolar nega tarixiy, ma’naviy va madaniy merosni avaylab-asrashi shartligi so‘raladi."},
 {t:"f",q:"«Kishi yurtida sulton bo‘lguncha, o‘z yurtingda cho‘pon bo‘l» hikmatini hayotiy misol bilan tushuntiring.",e:"O‘z yurtida inson yaqinlari orasida bo‘ladi, Vatanga xizmat qiladi; begona yurtdagi boylik va mansab Vatan sog‘inchini bosolmaydi."}]},

{id:"m2",n:"2-mavzu",t:"Oliy maqsadlar bilan yashash",b:1,
 map:{c:"Oliy maqsadlar",br:[
  {t:"Ustoz Zohid sabog‘i",e:"🏹",k:["kamon","bog‘langan ko‘z","nishon"],x:"Ko‘zi bog‘langan ustoz nishonga ura olmadi va shuni uqtirdi: maqsadga ko‘zing yetsagina erishasan."},
  {t:"Aniq maqsad",e:"🎯",k:["ko‘ra bilish","harakat","fe’l-atvor"],x:"Maqsadni aniq ko‘rish, unga erishishga ta’sir qiluvchi omillarni va kerakli fe’l-atvorni bilish muhim."},
  {t:"Insonning oliy maqsadi",e:"🌳",k:["daraxt ekish","ilm olish","ezgulik"],x:"Sharqona hikmatlarda daraxt ekish, ilm olish, oilaga va boshqalarga yaxshilik qilish oliy maqsad bo‘lishi kerakligi ta’kidlanadi."},
  {t:"Orzular izdoshi",e:"🐎",k:["Monti Roberts","ferma","ota daldasi"],x:"Monti amakisining e’tiroziga qaramay, otasining daldasi bilan orzusi sari intildi va unga erishdi."},
  {t:"Orzudan maqsadga",e:"📝",k:["reja","mustahkamlash","maqsad"],x:"Orzu shisha kabi mo‘rt, reja paydo bo‘lishi bilan u mustahkamlanadi va maqsadga aylanadi."}]},
 q:[
 {t:"m",q:"Ustoz Zohid shogirdiga o‘q uzishdan oldin nima qildirdi?",a:["Ko‘zini ro‘molcha bilan bog‘latdi","Kamonini boshqasiga almashtirdi","Nishonni daraxtdan oldirib tashladi","Yoyining ipini bo‘shatdirdi"],e:"Ustoz shogirdiga ro‘molcha uzatib, «ko‘zimni bog‘la» dedi."},
 {t:"m",q:"Ustoz Zohidning shogirdga bergan asosiy sabog‘i nima?",a:["Maqsadga ko‘zing yetsagina erishasan","Nishon yaqin bo‘lsa, albatta urasan","Kamon qimmat bo‘lsa, o‘q adashmaydi","Shogird ustozdan maslahat so‘ramaydi"],e:"Maqsadga ko‘z yetmasa, unga qanchalik yaqin turishning ahamiyati yo‘q."},
 {t:"m",q:"Ustoz ko‘zi ochiq holda g‘unchani qancha masofadan ura olardi?",a:["300 qadamdan","100 qadamdan","50 qadamdan","500 qadamdan"],e:"Ustoz: «Ko‘zim ochiqligida g‘unchani 300 qadamdan ura olaman», dedi."},
 {t:"m",q:"Donishmandlar fikricha, insoniyatning maqsadi nima?",a:["Odamlarni insoniylikka o‘rgatish","Imkon qadar ko‘p boylik yig‘ish","Eng baland mansabga ko‘tarilish","Boshqalardan ustun bo‘lib yashash"],e:"«Bilasizmi?» ruknida insoniyat maqsadi – odamlarni insoniylikka o‘rgatish, deyilgan."},
 {t:"m",q:"Monti Roberts yoshligida nimani orzu qilgan?",a:["Katta ferma va yilqichilik xo‘jaligini","Mashhur va yirik avtomobil ishlab chiqarish zavodini","Dengiz bo‘yidagi mehmonxonani","Yirik kitob nashriyotini"],e:"U ikki yuz gektarli ferma, otxonalar, otchopar va yilqichilik xo‘jaligini boshqarishni orzu qilgan."},
 {t:"m",q:"Montining orzusini eshitgan amakisi nima dedi?",a:["Hayot aniq rejalar ustiga qurilishi kerak","Orzu sari bugunoq yo‘lga chiqish kerak","Otang bilan maslahatlashish shart emas","Fermani birgalikda qurishni boshlaymiz"],e:"Amakisi uni xomxayol bo‘lmaslikka chaqirdi, ammo keyinchalik nohaq bo‘lganini tan oldi."},
 {t:"m",q:"Montiga orzusini saqlab qolishda kim dalda berdi?",a:["Otasi","Amakisi","Do‘sti Jek","Sinf rahbari"],e:"Otasi: «O‘z orzularingni omon saqlab qolishga haqqing bor, o‘g‘lim!» dedi."},
 {t:"m",q:"Darslikka ko‘ra, mo‘rt orzu nima paydo bo‘lishi bilan mustahkamlanadi?",a:["Reja","Omad","Boylik","Shuhrat"],e:"«Orzu shisha kabi mo‘rt, ammo reja paydo bo‘lishi bilan u mustahkamlanadi»."},
 {t:"tf",q:"Ustoz ko‘zi bog‘langan holda otgan o‘q g‘unchaga aniq tegdi.",a:false,e:"O‘q gul tugul daraxtga ham tegmadi."},
 {t:"tf",q:"Sharqona hikmatlarda daraxt ekish va ilm olish ham inson maqsadi sifatida tilga olinadi.",a:true,e:"Daraxt ekish, ilm olish va ezgulik ulashish insonning oliy maqsadi bo‘lishi lozim."},
 {t:"tf",q:"Montining amakisi keyinchalik ham o‘z e’tirozida qat’iy turib oldi.",a:false,e:"Yillar o‘tib u: «Men o‘shanda nohaq ekanman», deb tan oldi."},
 {t:"f",q:"O‘z orzuingizni maqsadga aylantirish uchun qanday reja tuzasiz?",e:"Maqsad aniq belgilanadi, unga ta’sir etuvchi omillar (kitob mutolaa qilish, tinimsiz harakat va b.) va qadamlar yoziladi, kerakli fazilatlar shakllantiriladi."}]},

{id:"m3",n:"3-mavzu",t:"Muvaffaqiyat – qunt va qat’iyat natijasi",b:1,
 map:{c:"Muvaffaqiyat",br:[
  {t:"Qat’iyat",e:"💪",k:["dadillik","sabot","«Bo‘lishi mumkin!»"],x:"Qat’iyat – dadillik, matonat, sabot; o‘z so‘zi va qarorida qattiq turish."},
  {t:"Qunt",e:"🔧",k:["hafsala","sabr-toqat","astoydil"],x:"Qunt – biror ishni astoydil berilib, sabr-toqat bilan bajarish ishtiyoqi."},
  {t:"Jeyms Dayson",e:"🧹",k:["changyutkich","15 yil","5126 namuna"],x:"Britaniyalik ixtirochi 15 yil davomida 5126 xil changyutkich namunasini yaratib, maqsadiga erishdi."},
  {t:"Halollik",e:"⚖️",k:["shukronalik","to‘g‘riso‘zlik","diyonat"],x:"To‘g‘riso‘zlik va halollik ustiga qurilgan umr – eng go‘zal umr. Qilayotgan ishdan odamlarga foyda bo‘lsin."},
  {t:"Vaqt va harakat",e:"⏳",k:["daqiqa","to‘xtamaslik","Konfutsiy"],x:"Vaqt ham quradi, ham yemiradi. Konfutsiy: muhimi – to‘xtab qolmaslik."}]},
 q:[
 {t:"m",q:"Jeyms Dayson nimani yaratish ustida 15 yil ishladi?",a:["Eng yaxshi changyutkichni","Eng yengil velosipedni","Eng tez avtomobilni","Eng ixcham telefonni"],e:"U eng yaxshi changyutkichni yaratish uchun 5126 xil namuna ixtiro qilgan."},
 {t:"m",q:"Daysonga istagan changyutkichini yaratishda kim yordam berdi?",a:["Yaponiyalik sarmoyador","Britaniyalik vazir","Koreyalik tadbirkor","Amerikalik professor"],e:"O‘z yurtida uni qo‘llamadilar, yaponiyalik sarmoyador yordam berdi."},
 {t:"m",q:"«Qunt» tushunchasining darslikdagi ma’nosi qaysi?",a:["Ishni sabr-toqat bilan astoydil bajarish ishtiyoqi","Tasodifan qo‘lga kiritilgan omad va yutuq","Boshqalarga buyruq berish va boshqarish mahorati","Ishni imkon qadar tez va yuzaki tugatish odati"],e:"Qunt – itoatkorlik, hafsala; ishni astoydil, sabr-toqat bilan bajarish ishtiyoqi."},
 {t:"m",q:"Matonat nima?",a:["Mustahkam iroda va chidamlilik","Tez xafa bo‘lish va arazlash","Ishni keyinga surish odati","O‘zgalardan yordam kutish"],e:"Matonat – mustahkam iroda, sabot, chidam, bardoshli bo‘lish."},
 {t:"m",q:"«Muhimi – to‘xtab qolmaslik» degan hikmat kimniki?",a:["Konfutsiy","Arastu","Sofokl","Beruniy"],e:"Konfutsiy: to‘xtamas ekansan, sekin yoki tez yurayotganing ahamiyatsiz."},
 {t:"m",q:"Murodulla Rayimov fikricha, dunyoda yengib bo‘lmaydigan kuch nima?",a:["Bir daqiqa","Katta boylik","Yuqori mansab","Tabiiy ofat"],e:"Daqiqalar yig‘ilib umrni hosil qiladi; vaqt ham quradi, ham yemiradi."},
 {t:"m",q:"Sharq donishmandlari bir harom luqma haqida nima degan?",a:["U tufayli ming halol luqma yo‘qotiladi","U ozgina bo‘lsa, insonga hech qanday zarari yo‘q","Uni bir yaxshi ish darhol yuvadi","U faqat boy odamga zarar qiladi"],e:"«Bir harom luqma deb, ming halol luqmani yo‘qotasan»."},
 {t:"m",q:"Shukronalik haqidagi matnga ko‘ra, inson qachon ruhan va ma’nan boy bo‘ladi?",a:["Ishidan odamlarga foyda tegsa","Katta meros qo‘lga kiritsa","Hammadan ko‘p pul topsa","Hech kimga bog‘lanmasa"],e:"Muhimi – qilayotgan ishingizdan insonlarga foyda bo‘lsin."},
 {t:"tf",q:"Darslikka ko‘ra, boylikka ega bo‘lgan odam albatta baxtli yashaydi.",a:false,e:"Inson boy bo‘lib baxtli yashamasligi, o‘rtahol bo‘lib baxtli yashashi mumkin."},
 {t:"tf",q:"Aniq reja va maqsad bilan yashaydigan insonlar munosib va muvaffaqiyatli umr kechiradi.",a:true,e:"Darslikda aynan shunday ta’kidlangan."},
 {t:"tf",q:"«Muvaffaqiyat kaliti» matnida muvaffaqiyat sizdan qat’iyatlilikni talab qilishi aytilgan.",a:true,e:"Muvaffaqiyatning siri oddiy va u qat’iyatlilikni talab qiladi."},
 {t:"f",q:"Qunt va qat’iyat muvaffaqiyatga qanday yordam berishini bir misolda ko‘rsating.",e:"Komiljon robotni bir yil davomida buzib, qayta yig‘ib g‘olib bo‘ldi; Dayson ham minglab urinishdan keyin maqsadiga erishdi."}]},

{id:"m4",n:"4–5-mavzu",t:"Umr-umid-sinov-imkoniyat",b:1,
 map:{c:"Umr va imkoniyat",br:[
  {t:"Umr – oqar daryo",e:"🌊",k:["suv – vaqt","xarsang","mayda tosh"],x:"Bobo tushuntiradi: daryo suvi vaqtga, katta xarsanglar katta maqsadlarga, mayda toshlar kichik maqsadlarga o‘xshaydi."},
  {t:"Vaqt qadri",e:"⌛",k:["zoye vaqt","hisob berish","vijdon"],x:"Kun oxirida vijdon oldida «nima ish qildim?» degan savolga dadil javob bera olsangiz, kun bekor o‘tmagan."},
  {t:"Kitob va ustoz",e:"📚",k:["beminnat","bilim","Rumiy"],x:"Kitob va ustoz-murabbiylar bilim beradi, evaziga hech narsa talab qilmaydi."},
  {t:"Po‘lat iroda",e:"🚗",k:["Chung Ju Yung","Poni","Hyundai"],x:"Velosipedda guruch tashigan o‘smir mehnat va iroda bilan «Hyundai» kompaniyasiga asos soldi."},
  {t:"Uddalash",e:"🧠",k:["Dorboz","Kiyosaki","sinov"],x:"Kiyosaki: «Uddalay olmayman» tushunchasi miyani qulflaydi, «Buni qanday amalga oshiraman?» savoli esa ishlashga majbur etadi."}]},
 q:[
 {t:"m",q:"Boboning o‘xshatishida daryoning shoshqaloq suvi nimani bildiradi?",a:["Vaqtni","Boylikni","Do‘stlikni","Salomatlikni"],e:"Suv – vaqt, xarsanglar – katta maqsadlar, mayda toshlar – kichik maqsadlar."},
 {t:"m",q:"Boboning fikricha, katta maqsadlarga qanday yetiladi?",a:["Kichik maqsadlar orqali","Faqat omad yordamida","Boshqalarning mehnati bilan","Hech qanday qiyinchiliksiz"],e:"«Hayotda ham katta maqsadlarga kichik maqsadlar orqali yetamiz»."},
 {t:"m",q:"Shamol va varrak misolida bobo nimani uqtirdi?",a:["Maqsadga mashaqqatli yo‘l yetkazadi","O‘yin paytida vaqt sekin o‘tadi","Varrakni faqat bahorda uchirish kerak","Qiyinchilikdan doim qochish kerak"],e:"Shamolsiz varrak ko‘tarilmaganidek, insonni maqsadga mashaqqat bilan bosgan yo‘li yetkazadi."},
 {t:"m",q:"Jaloliddin Rumiy nimani chin mo‘jiza deb ataydi?",a:["Beminnat kitobni","Falakdagi oftobni","Oqayotgan daryoni","Uchayotgan varrakni"],e:"«Mo‘jiza emasdir falakda oftob, mo‘jiza aslida beminnat kitob»."},
 {t:"m",q:"Chung Ju Yung do‘stlariga qanday maqsadini aytgan edi?",a:["Koreyada avtomobil ishlab chiqarishni","Koreyada katta guruch savdosi do‘konini ochishni","Yaponiyaga o‘qishga ketishni","Velosiped poygasida yutishni"],e:"Do‘stlari uning ustidan kulishgan, ammo u maqsadiga erishdi."},
 {t:"m",q:"Chung Ju Yung ishlab chiqargan birinchi koreys avtomobili qanday nomlangan?",a:["«Poni»","«Atlanta»","«Asan»","«Apple»"],e:"U Koreyada birinchi bo‘lib «Poni» nomli avtomobil ishlab chiqardi."},
 {t:"m",q:"Chung Ju Yung qanday nom olgan?",a:["Po‘lat iroda sohibi","Orzular izdoshi","Ilm fidoyisi","Dengiz sardori"],e:"1915-yilda tug‘ilgan Chung Ju Yung «Po‘lat iroda sohibi» nomini oldi."},
 {t:"m",q:"Abdulla Oripovning «Dorboz» she’rida «biz – ko‘zi ochiqlar» haqida nima deyiladi?",a:["Katta yo‘lda ham eplab yurolmaymiz","Arqon ustida dadil yura olamiz","Bulutlarga qo‘limiz bilan yetamiz","Dorbozdan ancha epchilroqmiz"],e:"Dorboz ko‘zini yumib arqonda yuradi, ba’zilar esa katta yo‘lda ham eplab yurolmaydi."},
 {t:"tf",q:"Robert Kiyosaki fikricha, «Uddalay olmayman» tushunchasi miyani qulflaydi.",a:true,e:"«Buni qanday amalga oshirsam bo‘ladi?» deyish esa ishlashga majbur etadi."},
 {t:"tf",q:"Darslikka ko‘ra, kitob bergan bilimi evaziga haq talab qiladi.",a:false,e:"Kitob bilim va taskin beradi, evaziga hech narsa talab qilmaydi."},
 {t:"tf",q:"Amir Temur tadbirsiz, loqayd kishilar ko‘pligi bitta shijoatli tadbirkordan yaxshiroq, degan.",a:false,e:"Aksincha: azmi qat’iy, hushyor bir kishi ming-minglab tadbirsiz, loqayd kishilardan yaxshiroq."},
 {t:"f",q:"Abu Mansur Moturidiyning «O‘tgan hayotingni o‘z mualliming deb bil» fikrini qanday tushunasiz?",e:"O‘tgan yutuq va xatolardan saboq olish, vaqtni qadrlash va kelgusida imkoniyatlardan to‘g‘ri foydalanish kerak."}]},

{id:"m5",n:"6-mavzu",t:"Tabiatni asrash – hayotni asrash",b:1,
 map:{c:"Tabiatni asrash",br:[
  {t:"Havo ifloslanishi",e:"🏭",k:["is gazi","transport 40%","zaharli gazlar"],x:"Atmosferani zaharlaydigan moddalarning 40% transportdan, 20% turli yoqilg‘ilardan, 15% ishlab chiqarishdan, 25% boshqa manbalardan chiqadi."},
  {t:"Orol dengizi",e:"🚢",k:["ichki havza","68 metr","baliq"],x:"Orol dunyoning to‘rtta eng yirik ichki suv havzasidan biri bo‘lgan, chuqurligi ayrim joyda qariyb 68 metrga yetgan."},
  {t:"Orol fojiasi",e:"🏜️",k:["Orolqum","sho‘rlanish","kemalar qabristoni"],x:"Qurigan joyda 5,5 million gektardan ziyod Orolqum sahrosi paydo bo‘ldi; sho‘rlanish 25 marta ortdi."},
  {t:"Suv va xavfsizlik",e:"💧",k:["BMT","oqilona foydalanish","manfaatlar tengligi"],x:"Prezident nutqida suv muammosi mintaqa mamlakatlari va xalqlari manfaatlarini teng hisobga olib hal etilishi ta’kidlangan."},
  {t:"Amaliy hissa",e:"🌱",k:["ko‘chat","loyiha","yechim"],x:"O‘quvchilar o‘z hududidagi tabiat va ekologik muammolarni o‘rganib, yechim taklif qiladi."}]},
 q:[
 {t:"m",q:"Atmosferani zaharlaydigan moddalarning eng katta ulushi qaysi manbadan chiqadi?",a:["Transportdan","Turli yoqilg‘ilardan","Ishlab chiqarishdan","Maishiy chiqindilardan"],e:"40% – transportdan, bu eng katta ulush."},
 {t:"m",q:"Bitta transatlantik havo laynerining parvozi qancha kislorodni yo‘q qiladi?",a:["50 tonna","5 tonna","200 tonna","1000 tonna"],e:"«Bilasizmi?» ruknida 50 tonna deb ko‘rsatilgan."},
 {t:"m",q:"1960-yillarda Orol qaysi qatorga kirgan?",a:["To‘rtta eng yirik ichki suv havzasi","Dunyodagi o‘nta eng chuqur okean botig‘i","Uchta eng uzun daryo havzasi","Beshta eng sovuq dengiz"],e:"Kaspiy dengizi, Viktoriya va Yuqori ko‘l qatorida turgan."},
 {t:"m",q:"Orolning qurigan qismi o‘rnida nima paydo bo‘ldi?",a:["Orolqum sahrosi","Qizilqum bog‘lari","Yangi suv ombori","To‘qay o‘rmonlari"],e:"5,5 million gektardan ziyod maydonda Orolqum sahrosi paydo bo‘ldi."},
 {t:"m",q:"Hozirda dengiz o‘rnidagi suratda ko‘rsatilgan joy qanday ataladi?",a:["Kemalar qabristoni","Baliqchilar bandargohi","Sayyohlar oroli","Dengizchilar bog‘i"],e:"Bir paytlar dengiz bo‘lgan joy «Kemalar qabristoni» deyiladi."},
 {t:"m",q:"Orol suvining sho‘rlanish darajasi necha marta ortgan?",a:["25 marta","5 marta","14 marta","68 marta"],e:"Sho‘rlanishning 25 marta ortishi baliqlarning qirilib ketishiga olib keldi."},
 {t:"m",q:"BMT Bosh kotibining Prezident qo‘llab-quvvatlagan pozitsiyasi qaysi?",a:["Suv, tinchlik va xavfsizlik muammolari o‘zaro bog‘liq","Suv muammosini har bir davlat boshqalarsiz, yolg‘iz hal qiladi","Ekologiya xavfsizlik masalasiga aloqador emas","Daryo suvi faqat sanoat uchun sarflanishi kerak"],e:"Bu uchta muammo o‘zaro chambarchas bog‘liq."},
 {t:"m",q:"Preventiv diplomatiya nimaga qaratilgan?",a:["Kelishmovchilik va mojaroning oldini olishga","Savdo bojlarini keskin oshirishga","Chegaradagi harbiy qo‘shinlar sonini ko‘paytirishga","Sayyohlik yo‘nalishlarini ochishga"],e:"U kelishmovchilik paydo bo‘lishi, mojaroga aylanishi va tarqalishining oldini olishga qaratilgan."},
 {t:"tf",q:"Orol suv havzasida ilgari yiliga 35 ming tonnagacha baliq ovlangan.",a:true,e:"Darslikda shu ma’lumot berilgan."},
 {t:"tf",q:"Amudaryo va Sirdaryodan Orolga quyiladigan suv keyingi ellik yilda ko‘paygan.",a:false,e:"Aksincha, qariyb 5 barobar kamaygan."},
 {t:"tf",q:"Zaharli kimyoviy moddalar inson salomatligiga katta zarar keltiradi.",a:true,e:"Ularning atrof-muhitda barqarorligi va ko‘chib yurishi salomatlikka zarar yetkazadi."},
 {t:"f",q:"Yashash joyingizdagi bitta ekologik muammoni ayting va yechim taklif qiling.",e:"Masalan, chiqindi tashlanishi: chiqindi qutilari qo‘yish, saralash, hashar o‘tkazish, ko‘chat ekish va targ‘ibot olib borish."}]},

{id:"m6",n:"7-mavzu",t:"Inson axloqi bilan go‘zal",b:2,
 map:{c:"Go‘zal axloq",br:[
  {t:"Xushmuomalalik",e:"😊",k:["tabassum","shirin so‘z","muomala"],x:"Donishmand eng yaxshi fazilatlar deb tabassum, shirin so‘z va xushmuomalalikni aytgan."},
  {t:"Odob",e:"🎩",k:["xulq-atvor","yurish-turish","el-yurt orasida"],x:"Odob – odamning jamoatda o‘zini tutishi, muomalasi, bo‘sh vaqtini tashkil etishi va kundalik xulqini ifodalovchi xususiyat."},
  {t:"O‘z aybini bilish",e:"🪞",k:["Firdavsiy","ayb","kamtarlik"],x:"Firdavsiy: o‘z aybini bilgan odam boshqalar aybini so‘zlamas edi."},
  {t:"Kapalak rivoyati",e:"🦋",k:["donishmand","hasadgo‘y","o‘z qo‘lingda"],x:"Hasadgo‘y donishmandni uyaltirmoqchi bo‘ldi, donishmand esa: «Hammasi o‘z qo‘lingda», dedi."},
  {t:"Do‘st tanlash",e:"🤝",k:["fazilat","axloqsiz odat","tarbiyali do‘st"],x:"Do‘stlashishdan oldin insonning axloqiy fazilatlariga e’tibor berish kerak."}]},
 q:[
 {t:"m",q:"Donishmand qaysi fazilatlarni eng yaxshi fazilatlar deb sanagan?",a:["Tabassum, shirin so‘z, xushmuomalalik","Boylik, mansab, obro‘li qarindoshlar","Kuch, tezlik, bellashuvda g‘oliblik","Sukut, yolg‘izlik, hammadan uzoqlik"],e:"U «Tabassum qilmoqlik, shirin so‘zlamoqlik, xushmuomala bo‘lmoqlik» deb javob berdi."},
 {t:"m",q:"Do‘konda onasi tanishi bilan suhbatlashib qolganda Anvar avval nima qildi?",a:["Salom berib, sekin chetga o‘tib turdi","Salom bermay ko‘chaga chiqib ketdi","Baland ovozda onasini koyidi","Shirinliklarni sochib yubordi"],e:"Bola salom berib, chetga o‘tib turdi; keyinroq tadbirga kech qolayotganini eslatdi."},
 {t:"m",q:"Kapalak rivoyatida hasadgo‘y odamning maqsadi nima edi?",a:["Donishmandni xalq oldida uyaltirish","Donishmanddan ilm va hayot saboqlarini o‘rganish","Kapalakni unga sovg‘a qilish","Undan kasb sirini so‘rash"],e:"U har qanday javobda donishmandni adashgan qilib ko‘rsatmoqchi edi."},
 {t:"m",q:"«Kapalak tirikmi yoki o‘likmi?» degan savolga donishmand nima dedi?",a:["Hammasi o‘z qo‘lingda","Kapalak albatta tirik","Kapalak allaqachon o‘lik","Buni men bilolmayman"],e:"Natija so‘rovchining o‘z qaroriga bog‘liq edi."},
 {t:"m",q:"Odob deganda nima tushuniladi?",a:["Jamoatda o‘zini tutish va muomala xususiyati","Insonning bo‘y-basti, yuz tuzilishi va tashqi qiyofasi","Kasb bo‘yicha texnik mahorat darajasi","Odamning mol-mulki va daromadi miqdori"],e:"Odob kundalik xulq-atvor, yurish-turish va muomalani ifodalaydi."},
 {t:"m",q:"«O‘zining aybini bilganda odam, boshqalar aybini so‘zlamasdi ham» satrlari kimniki?",a:["Abulqosim Firdavsiy","Alisher Navoiy","Jaloliddin Rumiy","Abu Rayhon Beruniy"],e:"Bu satrlar Firdavsiy nomidan keltirilgan."},
 {t:"m",q:"Do‘stlashmoqchi bo‘lgan odamda axloqsiz odatlar bo‘lsa, darslik nima tavsiya qiladi?",a:["Undan uzoqroq yurishni","Uning odatiga moslashishni","Bunga e’tibor bermaslikni","Hammaga ovoza qilishni"],e:"Avval axloqiy fazilatlariga qarash, axloqsiz odatlari bo‘lsa uzoqroq yurish kerak."},
 {t:"m",q:"«Ma’naviyat xazinasidan» ruknida odamlarga muomalada xulq qanday bo‘lishi aytilgan?",a:["Chiroyli","Qattiqqo‘l","Befarq","Mag‘rur"],e:"«Barcha ishlaringizda to‘g‘ri bo‘ling, odamlarga muomalada xulqingiz chiroyli bo‘lsin!»"},
 {t:"tf",q:"Kapalak rivoyatidagi donishmandga odamlar maslahat so‘rab kelar va unga ishonar edi.",a:true,e:"U hammaga yordam bergan, yoshi, donoligi va tajribasi hurmat qilingan."},
 {t:"tf",q:"Odob tushunchasiga bo‘sh vaqtni qanday tashkil etish kirmaydi.",a:false,e:"Darslik ta’rifida bo‘sh vaqtni tashkil etish ham odobga kiritilgan."},
 {t:"tf",q:"Darslikdagi hikmatga ko‘ra, barcha yaxshilik xushxulqlikdadir.",a:true,e:"«Barcha yaxshilik – xushxulqlikdadir» degan hikmat keltirilgan."},
 {t:"f",q:"Donishmandning «Hammasi o‘z qo‘lingda» degan javobi hayotda nimani o‘rgatadi?",e:"Yaxshilik yoki yomonlik qilish, o‘zgalar hayotiga qanday ta’sir etish insonning o‘z tanlovi va mas’uliyatiga bog‘liq."}]},

{id:"m7",n:"8-mavzu",t:"Inson odobida aks etuvchi fe’l-atvor",b:2,
 map:{c:"Odob va fe’l-atvor",br:[
  {t:"Yaxshini ko‘rish",e:"⚪",k:["qora nuqta","oq varaq","xato"],x:"Biz ko‘pincha insonning kichik xatosiga diqqat qilib, barcha to‘g‘ri ishlarini unutib qo‘yamiz."},
  {t:"O‘zini tarbiyalash",e:"🧘",k:["Beruniy","his-tuyg‘u","illat"],x:"Beruniy: inson hislarini boshqarishga, illatlarni asta-sekin bartaraf etishga qodir."},
  {t:"Axloq qoidalari",e:"📏",k:["rostgo‘ylik","tinglash","xotirjamlik"],x:"Rost gapiring, suhbatdoshni tinglang, g‘azablanmang, xatoingiz uchun boshqalarni ayblamang."},
  {t:"Ko‘ngil asrash",e:"🏺",k:["kintsugi","chinni idish","ko‘ngil"],x:"Singan idishni oltin bilan yamasa ham izi qoladi; singan ko‘ngilni asl holiga keltirib bo‘lmaydi."},
  {t:"Ezgulik asosi",e:"🌟",k:["Ibn Sino","halollik","kattalarga hurmat"],x:"Ibn Sino halollik, adolat, xushmuomalalik, samimiy do‘stlik va yordamni barcha ezgulikning asosi deydi."}]},
 q:[
 {t:"m",q:"Nazorat ishida o‘qituvchi tarqatgan varaqda nima bor edi?",a:["O‘rtasida kichik qora nuqta","O‘nta juda murakkab nazorat savoli","Katta rangli surat","Tugallanmagan hikoya"],e:"Kichik qora nuqtani hisobga olmaganda, qog‘oz bo‘m-bo‘sh edi."},
 {t:"m",q:"Qora nuqta voqeasidan qanday xulosa chiqadi?",a:["Kichik xato tufayli yaxshi ishlarni unutmaslik kerak","Nazorat ishiga oldindan tayyorlanish shart emas","Har doim ko‘pchilik yozgan javobni yozish kerak","Insonning faqat kamchiligiga qarab baho beriladi"],e:"Yaxshi narsalar qolib, yomonlikka diqqat qilish – katta xato."},
 {t:"m",q:"Darslikka ko‘ra, obro‘ga erishishning eng halol yo‘li qaysi?",a:["Kamtarlik","Maqtanish","Boylik","Qattiqqo‘llik"],e:"«Bilasizmi?» ruknida: obro‘ga erishishning eng halol yo‘li – kamtarlik."},
 {t:"m",q:"Inson o‘z ruhi va tanini tarbiyalab, illatlarni bartaraf etishga qodirligi haqidagi fikr kimniki?",a:["Abu Rayhon Beruniy","Kaykovus","Abulqosim Firdavsiy","Mahmud Zamaxshariy"],e:"Beruniy axloq kitoblaridagi usullar bilan illatlarni yo‘qotish mumkinligini yozgan."},
 {t:"m",q:"Yaponlarning kintsugi san’ati nima?",a:["Singan chinnini oltin bilan yamash","Qog‘ozdan turli shakllar yasash","Gullardan guldasta tuzish","Ipak matoga naqsh tikish"],e:"Usta idish bo‘laklarini oltin suvi bilan qayta yamagan."},
 {t:"m",q:"Kintsugi misolida inson ko‘ngli haqida nima deyiladi?",a:["Singach, asl holiga keltirib bo‘lmaydi","Oltin sovg‘a bilan darrov tiklanadi","Vaqt o‘tsa, hech qanday iz qolmaydi","Uni sindirish deyarli mumkin emas"],e:"Ko‘ngil qimmatbaho idish kabi – sinsa, oldingidek bo‘lmaydi."},
 {t:"m",q:"Muvaffaqiyatli muloqotning siri darslikda nimada ko‘rsatilgan?",a:["Suhbatdoshni tinglay olishda","Baland ovozda gapirishda","Oxirgi so‘zni aytishda","Ko‘proq bahslashishda"],e:"«Muvaffaqiyatli muloqotning siri suhbatdoshingizni tinglay olishingizda»."},
 {t:"m",q:"Kaykovusning «Qobusnoma»sida yaxshilik qilgan odam haqida nima deyiladi?",a:["Unga ham shunchalik zavq nasib etadi","U evaziga albatta haq talab qiladi","Uning mol-mulki tezda kamayadi","U bundan faqat charchoq sezadi"],e:"Saxovatdan boshqa kishi shod bo‘lgani kabi, yaxshilik qiluvchiga ham zavq nasib etadi."},
 {t:"tf",q:"Axloq qoidalariga ko‘ra, birovning aybini aytishdan avval o‘zingizdan ayb qidirish kerak.",a:true,e:"O‘z xatoingiz uchun boshqalarni ayblamang."},
 {t:"tf",q:"Rost gapirish zararimizga bo‘lsa, yolg‘on gapirish mumkin, deb o‘rgatiladi.",a:false,e:"O‘zingiz zarariga bo‘lsa ham doimo rost gapirish kerak."},
 {t:"tf",q:"Ibn Sino kattalar hurmatini joyiga qo‘yish va kichiklarga shafqatni ham ezgulik asoslariga kiritgan.",a:true,e:"U halollik, adolat, xushmuomalalik qatorida bularni ham sanaydi."},
 {t:"f",q:"Inson ko‘nglini nimalar og‘ritadi va bunga yo‘l qo‘ymaslik uchun nima qilasiz?",e:"Qo‘pol so‘z, yolg‘on, hurmatsizlik, ayblash ko‘ngilni sindiradi; rostgo‘y, xushmuomala, g‘azabini tiyadigan bo‘lish va o‘ziga ravo ko‘rmaganni boshqaga ravo ko‘rmaslik kerak."}]},

{id:"m8",n:"9-mavzu",t:"Insonlarni birlashtiruvchi umuminsoniy xislatlar",b:2,
 map:{c:"Umuminsoniy xislatlar",br:[
  {t:"Chin do‘stlik",e:"🤝",k:["uch do‘st","moddiy yordam","dalda"],x:"Qiyin ahvolda uchinchi do‘st koyimay va maqtanmay, mablag‘ berib, ko‘nglini ko‘tardi."},
  {t:"Rostgo‘ylik",e:"🗣️",k:["onaga va’da","qirq tanga","qaroqchilar"],x:"Yigit onasiga bergan va’dasiga sodiq qolib, qaroqchilarga ham rost gapirdi."},
  {t:"Mehr va saxovat",e:"💞",k:["birlashtiradi","burch","qadr"],x:"Insonlarni bir-biriga mehri va saxovati birlashtiradi; o‘zgalar oldidagi burchni unutmaslik kerak."},
  {t:"Birgalik qoidalari",e:"🏘️",k:["ahillik","bir kishi hamma uchun","mulkni hurmat"],x:"Ahillik va o‘zaro hurmatga amal qilish, yaxshilikka yaxshilik bilan javob berish, o‘zgalar mulkini hurmat qilish."},
  {t:"Sabr va sir saqlash",e:"🔐",k:["sabr","omonat gap","kechirim"],x:"Omonat gapni boshqaga aytmaslik, sabrli, kechirimli va tejamkor bo‘lish."}]},
 q:[
 {t:"m",q:"«Chin do‘stlik» hikoyasida birinchi do‘st nima qildi?",a:["Aybni yigitning o‘ziga qo‘yib koyidi","Unga darhol kerakli mablag‘ berdi","Uni yangi ishga joylab qo‘ydi","Ko‘nglini iliq so‘z bilan ko‘tardi"],e:"Birinchi do‘sti bu holatga o‘zi sababchi ekanini yuziga soldi."},
 {t:"m",q:"Qaysi do‘st chinakam yordam ko‘rsatdi?",a:["Mablag‘ berib, dalda bergan uchinchisi","Pul topishini maqtab bergan ikkinchisi","Qattiq koyib tanqid qilgan birinchisi","Faqat uzundan-uzoq nasihat qilgan kishi"],e:"Uchinchi do‘sti mablag‘ tutqazib, tushkunlikka tushmaslikni so‘radi."},
 {t:"m",q:"Ilm izlab ketayotgan yigitdan onasi qanday va’da oldi?",a:["Hech qachon odamlarni aldamaslik","Bir yil ichida uyga qaytib kelish","Tangalarni hech kimga bermaslik","Karvondan ajralib yurmaslik"],e:"Ona har qanday holatda ham aldamaslikka va’da so‘radi."},
 {t:"m",q:"Onasi yigitning choponiga nima tikib bergan edi?",a:["Zarurat uchun tangalar","Oiladan qolgan qadimiy tumor","Yo‘l xaritasi","Maktub"],e:"Choponida qirq dona tanga bor edi."},
 {t:"m",q:"Nima uchun birinchi qaroqchi yigitdan nari ketdi?",a:["Uni hazillashyapti deb o‘yladi","Karvonboshidan qo‘rqib ketdi","Tangalarni allaqachon olgan edi","Yigitga rahmi kelib qoldi"],e:"Yigit rostini aytdi, qaroqchi esa ishonmadi."},
 {t:"m",q:"Darslikka ko‘ra, insonlarni nima birlashtiradi?",a:["Bir-biriga mehri va saxovati","Bir xil kiyinish odati","Boylikka bo‘lgan raqobat","Bir-biridan qo‘rqish hissi"],e:"«Ularning bir-biriga bo‘lgan mehri va saxovati»."},
 {t:"m",q:"«Ma’naviyat xazinasidan»da kishi uchun eng foydali va dilni yorishtiruvchi narsa nima deyilgan?",a:["Qanoat","Shuhrat","Boylik","Mansab"],e:"Eng foydali va dilni yorituvchi narsa – qanoat."},
 {t:"m",q:"Sabr haqida mavzudagi qoidada nima deyiladi?",a:["U barcha xursandchiliklar kaliti","U faqat keksalarga xos odat","U harakatsizlikning boshlanishi","U muloqotga to‘sqinlik qiladi"],e:"«Sabr barcha xursandchiliklar kalitidir»."},
 {t:"tf",q:"Yigit qaroqchilarga yonida hech narsa yo‘qligini aytdi.",a:false,e:"U choponida qirq tanga borligini rost aytdi."},
 {t:"tf",q:"Umuminsoniy qoidalar qatorida o‘zgalar mulkini hurmat qilish ham bor.",a:true,e:"«O‘zgalarning mulkini hurmat qiling»."},
 {t:"tf",q:"Mavzuda omonat qilib aytilgan gapni boshqaga aytmaslik, sir saqlash tavsiya etiladi.",a:true,e:"«Sir saqlashni o‘rganing» deyilgan."},
 {t:"f",q:"Uch do‘stdan qaysi birining yo‘lini tutgan bo‘lardingiz va nega?",e:"Uchinchi do‘st yo‘li ma’qul: koyish va maqtanish emas, amaliy yordam va dalda qiyin paytda kuch beradi."}]},

{id:"m9",n:"10–11-mavzu",t:"Baxtiyor hayotning ustunlari",b:2,
 map:{c:"Baxtiyor hayot",br:[
  {t:"Arastu ta’limoti",e:"🏺",k:["baxtiyorlik","axloq","mushohada"],x:"Arastu: yashashdan maqsad – baxtiyorlik; baxtli yashash uchun aqlning o‘zi yetmaydi, axloq ham muhim."},
  {t:"Aql va nafs",e:"⚖️",k:["bilim","nafs","ochko‘zlik"],x:"Aql nafsdan ustun kelsa, mushohada sodir bo‘ladi; bilim nafs ustidan g‘olib bo‘lishga yordam beradi."},
  {t:"Ichki sifatlar",e:"🐺",k:["Rumiy","ustun tabiat","oltin va mis"],x:"Rumiy: insonda yaxshi va yomon sifatlar bor, qaysi biri ustun bo‘lsa, inson shunga aylanadi."},
  {t:"Qo‘shni haqi",e:"🏡",k:["Abdulloh ibn Umar","ulashish","aziyat bermaslik"],x:"Qo‘shniga yaxshilik qilish va aziyat yetkazmaslik komillik sari yetaklaydi."},
  {t:"Ilm odobi",e:"📖",k:["G‘azzoliy","sukut","amal"],x:"G‘azzoliy: ilmning avvali sukut, keyin tinglash, yod olish, amal qilish, tarqatish va o‘rgatish."}]},
 q:[
 {t:"m",q:"Arastu fikricha, insonning yashashdan maqsadi nima?",a:["Baxtiyorlik","Shon-shuhrat","Boylik","Hokimiyat"],e:"Arastu «Insonning yashashdan maqsadi – baxtiyorlik» degan xulosaga kelgan."},
 {t:"m",q:"Arastuning fikriga ko‘ra, to‘g‘ri mushohada doimo nimaga tayanadi?",a:["Axloqqa","Omadga","Boylikka","Odatga"],e:"Shuning uchun baxtli yashashda aql bilan birga axloq ham muhim."},
 {t:"m",q:"Insonga nafs ustidan g‘olib kelishga nima yordam beradi?",a:["Bilim","Mol-mulk","Tana kuchi","Chiroyli kiyim"],e:"«Bilim insonga nafs ustidan g‘olib kelishiga yordam beradi»."},
 {t:"m",q:"Rumiy inson vujudini nimaga o‘xshatadi?",a:["O‘rmonga","Dengizga","Saroyga","Daryoga"],e:"Vujudda minglab «bo‘rilar», yaxshi-yomon sifatlar bor."},
 {t:"m",q:"Abdulloh ibn Umar tuya so‘yganda xizmatkorga qayta-qayta nimani eslatdi?",a:["Qo‘shnini unutmaslikni","Tuyani bozorga eltishni","Mehmonlarni kutib olishni","Terini sotib yuborishni"],e:"Boshqa dinga e’tiqod qiluvchi qo‘shniga go‘sht ajratishni takrorlab so‘radi."},
 {t:"m",q:"Kishi oilasidan keyin eng ko‘p kimlar bilan muloqot qiladi?",a:["Qo‘shnilari bilan","Sayyohlar bilan","Savdogarlar bilan","Amaldorlar bilan"],e:"Shuning uchun o‘zgalarga munosabat qo‘shniga munosabat orqali shakllanadi."},
 {t:"m",q:"G‘azzoliy fikricha, ilmning avvali nima?",a:["Sukut qilish","Boshqaga o‘rgatish","Bahs yuritish","Kitob yozish"],e:"Ilmning avvali sukut, keyin tinglash, yod olish, amal qilish va tarqatish."},
 {t:"m",q:"Buvining tug‘ilgan kunida u onaga nimani tayinladi?",a:["Homilador qo‘shni kelinga ovqat chiqarishni","Barcha mehmonlarga qimmatbaho sovg‘a tarqatishni","Kabobni faqat erkaklarga berishni","Hovli eshigini mahkam yopib qo‘yishni"],e:"Tutun hidi dimog‘iga kirgandir deb, og‘iroyoq qo‘shni kelinga somsa va kabob ulashishni so‘radi."},
 {t:"tf",q:"Arastu baxtiyor yashash uchun aqlli bo‘lishning o‘zi yetarli, deb hisoblagan.",a:false,e:"Aql yetarli emas, axloq ham muhim."},
 {t:"tf",q:"Mavzudagi qo‘shnichilik haqlariga qo‘shni bemor bo‘lsa, holini so‘rash ham kiradi.",a:true,e:"Yordam berish, ta’ziya bildirish, xabar olish ham shular qatorida."},
 {t:"tf",q:"Rumiyga ko‘ra, tanga tarkibida oltin misdan ko‘p bo‘lsa, u oltin hisoblanadi.",a:true,e:"Xuddi shunday, insonda qaysi tabiat ustun bo‘lsa, u shunga aylanadi."},
 {t:"f",q:"Sizningcha, baxtiyor hayotning eng muhim ikki «ustuni» qaysi? Asoslang.",e:"Masalan, axloq va bilim: bilim nafsni yengishga yordam beradi, axloq to‘g‘ri mushohada va yaxshi munosabatlarga asos bo‘ladi; mehr-oqibat ham muhim."}]},

{id:"m10",n:"12-mavzu",t:"Hammasi o‘z qo‘limizda",b:2,
 map:{c:"Tanlov o‘zimizda",br:[
  {t:"Munosabat va tanlov",e:"🧭",k:["Tarbiya kompasi","hamyon","qaror"],x:"Voqealar har lahzada yuz berishi mumkin, ularning hayotimizga ta’sirini bizning munosabatimiz belgilaydi."},
  {t:"Xayrli ishlar",e:"🤲",k:["yarashtirish","tabassum","savob"],x:"Arazlashganlarni yarashtirish, ulovga minishga yordamlashish, tabassum bilan yaxshi so‘z aytish – xayrli ishlar."},
  {t:"Oltin qoida",e:"✨",k:["Konfutsiy","ravo ko‘rma","yaxshilik"],x:"Konfutsiy: o‘zingga ravo ko‘rmaganni boshqaga ham ravo ko‘rma."},
  {t:"101 askar",e:"🎖️",k:["Amersfort","asirlik","9-aprel"],x:"Niderlandiyada 101 o‘zbek askari dafn etilgan; har yili 9-aprelda yod etiladi."},
  {t:"Non voqeasi",e:"🍞",k:["101 bo‘lak","matonat","shukr"],x:"Och asirlar nonga tashlanmadi: uni o‘pib, yoshi kattaga berishdi va teng 101 bo‘lakka bo‘lishdi."}]},
 q:[
 {t:"m",q:"Mavzuga ko‘ra, voqealarning hayotimizga ta’sirini nima belgilaydi?",a:["Bizning munosabatimiz","Faqat tasodif","Boshqalarning fikri","Boyligimiz miqdori"],e:"Voqealar kutilmaganda bo‘ladi, ta’sirini esa munosabatimiz belgilaydi."},
 {t:"m",q:"«O‘zingga ravo ko‘rmaganni boshqaga ham ravo ko‘rma» maslahatini kim bergan?",a:["Konfutsiy","Arastu","Sofokl","Kaykovus"],e:"Xitoylik donishmand Konfutsiy bir umrlik maslahat sifatida shuni aytgan."},
 {t:"m",q:"O‘zbek askarlari dafn etilgan Lyozdin qabristoni qaysi shaharda?",a:["Amersfort","Smolensk","Varshava","Samarqand"],e:"Niderlandiyaning Amersfort shahrida."},
 {t:"m",q:"Askarlar asosan qaysi hududdan edi?",a:["Samarqanddan","Andijondan","Xorazmdan","Farg‘onadan"],e:"Aksariyati samarqandlik yigitlar bo‘lgan."},
 {t:"m",q:"Natsistlar non tashlab, nimani suratga olmoqchi edi?",a:["Asirlarning ovqat uchun talashishini","Asirlarning mehnat qilayotganini","Lagerdagi bayram dasturxonini","Askarlarning ozod etilishini"],e:"Maqsad niderlandlarni qo‘rqitish uchun maxsus film ishlash edi."},
 {t:"m",q:"Eng yosh asir nonni olib nima qildi?",a:["Peshonasiga surtib, kattasiga uzatdi","Shu zahoti o‘zi yeb tugatdi","Kamera tutgan soldatlar tomonga irg‘itdi","Cho‘ntagiga yashirib qo‘ydi"],e:"U nonni peshonasiga surtib o‘pdi va yoshi katta asirga berdi."},
 {t:"m",q:"Yoshi katta asir nonni nima bilan bo‘ldi?",a:["Qoshiq bilan","Pichoq bilan","Ip bilan","Qilich bilan"],e:"Nonni qoshiq bilan 101 bo‘lakka bo‘lib tarqatdi."},
 {t:"m",q:"101 askar xotirasiga bag‘ishlangan marosim qaysi sanada o‘tadi?",a:["9-aprelda","9-mayda","2-dekabrda","1-sentabrda"],e:"9-aprel Xotira marosimi sifatida belgilangan."},
 {t:"tf",q:"Asirlar och bo‘lsa ham, nonga o‘zini otmadi.",a:true,e:"Ular tartib va qadrni saqlab, nonni teng bo‘lishdi."},
 {t:"tf",q:"«Non voqeasi»dan keyin natsistlar askarlarni darhol ozod qildi.",a:false,e:"Ular qiynoqqa solindi; 24 nafari vafot etdi, 77 nafari qatl qilindi."},
 {t:"tf",q:"Arazlashib qolgan kishilarni yarashtirish darslikda savob ish deb ko‘rsatilgan.",a:true,e:"«Ma’naviyat xazinasidan» ruknida shunday deyilgan."},
 {t:"f",q:"Yo‘lda pul to‘la hamyon topib olsangiz, nima qilasiz va nega?",e:"Egasini topish choralarini ko‘rish kerak (kattalar yoki mas’ullarga murojaat qilish); bu halollik va vijdonlilik belgisi."}]},

{id:"m11",n:"13-mavzu",t:"Inson umri ...",b:3,
 map:{c:"Umr va salomatlik",br:[
  {t:"Hayot – ne’mat",e:"🕊️",k:["dinlar","qasd qilmaslik","qadr"],x:"Dinlar zo‘ravonlik va o‘z joniga qasd qilishni taqiqlaydi. Islomda hayot Alloh bergan ne’mat sanaladi."},
  {t:"Tamaki zarari",e:"🚭",k:["1,1 milliard","6 million","zaharli unsur"],x:"Dunyoda 1,1 milliard kashanda bor, yiliga ularning 6 millioni kasalliklardan vafot etadi."},
  {t:"Nosvoy xavfi",e:"⚠️",k:["nikotin","infeksiya","gepatit"],x:"Nos oshqozon infeksiyalari, virusli gepatit yuqishiga va nikotinga qaramlikka olib kelishi mumkin."},
  {t:"O‘smir salomatligi",e:"🧠",k:["zehn","xotira","qaramlik"],x:"Chekish o‘smirning ruhiy rivojlanishiga zarar qiladi: zehn pasayadi, xotira yomonlashadi."},
  {t:"Sog‘lom turmush",e:"🍏",k:["gigiyena","tibbiy madaniyat","Avloniy"],x:"Avloniy: o‘qish, o‘qitish, o‘rganish uchun insonga sog‘lom badan zarur."}]},
 q:[
 {t:"m",q:"Buddaviylikda o‘z joniga qasd qilish qanday baholanadi?",a:["Hayotga nisbatan noshukurlik","Jasoratning oliy ko‘rinishi","Shaxsning oddiy tanlovi","Kechirimlilik belgisi"],e:"Bu insonning hayotga nisbatan noshukurligi sanaladi."},
 {t:"m",q:"Islom ta’limotiga ko‘ra, hayot ne’matiga qanday munosabatda bo‘lish kerak?",a:["Qadriga yetib, xayrli ishlar qilish","Unga beparvo qarab yashash","Faqat o‘z huzuri uchun sarflash","Kelajak haqida umuman o‘ylamaslik"],e:"Har soat, har daqiqada xayrli va savobli ishlar qilish talab etiladi."},
 {t:"m",q:"Darslik ma’lumotiga ko‘ra, sayyoramizda qancha kashanda bor?",a:["1,1 milliard","6 million","400 million","4,1 milliard"],e:"1,1 milliard nafar; har yili 6 millioni hayotdan ko‘z yumadi."},
 {t:"m",q:"Og‘iz bo‘shlig‘i, halqum va o‘pka saratonining necha foizi chekish oqibatida yuzaga keladi?",a:["80 foizi","15 foizi","40 foizi","55 foizi"],e:"Darslikda 80 foiz deb ko‘rsatilgan."},
 {t:"m",q:"Nos tarkibidagi asosiy ta’sir qiluvchi modda nimadan olinadi?",a:["Tamakidan","Choydan","Qahvadan","Yalpizdan"],e:"Asosiy modda tamaki bo‘lgani uchun nikotinga qaramlik paydo bo‘ladi."},
 {t:"m",q:"Chekish o‘smirlarning ruhiy rivojlanishiga qanday ta’sir qiladi?",a:["Zehn pasayadi, xotira yomonlashadi","Zehn o‘tkirlashadi, xotira ortadi","Diqqat va quvvat doim oshadi","Hech qanday ta’sir sezilmaydi"],e:"Darslik: zehni pasayadi, xotira yomonlashadi."},
 {t:"m",q:"«Sog‘ badanga ega bo‘lmagan insonlar barcha amallarinda kamchilik qilurlar» fikri kimniki?",a:["Abdulla Avloniy","Abdulla Oripov","Alisher Navoiy","Abu Nasr Forobiy"],e:"Bu Avloniyning sog‘lom badan haqidagi fikri."},
 {t:"m",q:"Nosvoy iste’mol qilgan odam qaysi kasallikni yuqtirib olishi mumkin?",a:["Virusli gepatit","Yuqumli qizamiq","Bezgak","Suvchechak"],e:"Oshqozon infeksiyalari va virusli gepatit tilga olingan."},
 {t:"tf",q:"Akmal tumov bo‘lganida hamshiraning maslahatiga amal qilib, tez tuzaldi.",a:false,e:"U e’tiborsizlik qildi va hafta davomida isitmalab uyda qoldi."},
 {t:"tf",q:"Diniy ta’limotlar o‘ziga va o‘zgalar joniga qasd qilishni qat’iyan taqiqlaydi.",a:true,e:"Zo‘ravonlik va qon to‘kish ham taqiqlanadi."},
 {t:"tf",q:"Tamaki tarkibidagi zaharli unsurlar yurak-qon tomirlarining torayishiga sabab bo‘lishi mumkin.",a:true,e:"O‘pka, tish, ko‘z va oshqozon-ichakka ham zarar yetkazadi."},
 {t:"f",q:"Sog‘lom turmush tarzi uchun qaysi qoidalarga amal qilasiz?",e:"Gigiyenaga rioya qilish, zararli odatlardan (tamaki, nos, ichkilik, giyohvandlik) saqlanish, kasal bo‘lsa shifokorga ko‘rinish."}]},

{id:"m12",n:"14-mavzu",t:"Ogohlik",b:3,
 map:{c:"Ogohlik",br:[
  {t:"Ogohlik ma’nosi",e:"👁️",k:["e’tibor","tahlil","taqqoslash"],x:"Ogohlik – atrofga sinchkov bo‘lish, yangiliklarni tahlil qilib, o‘z xatti-harakatini belgilay olish."},
  {t:"Befarqlik xavfi",e:"😶",k:["Rumiy","loqayd","g‘aflat"],x:"Rumiy: befarq va loqayddan qo‘rq, chunki u o‘g‘ri va qotilga yo‘l qo‘yib beradi."},
  {t:"G‘animat bilish",e:"⏰",k:["sog‘liq","yoshlik","hayot"],x:"Besh narsani avvaldan qadrlash: sog‘liq, yoshlik, boylik, xotirjamlik, hayot."},
  {t:"Ko‘rinmas qarmoq",e:"📱",k:["Lola","xavfli o‘yin","ona e’tibori"],x:"Lola ijtimoiy tarmoqdagi xavfli o‘yin domiga tushdi, onasining ziyrakligi uni qutqardi."},
  {t:"Mas’uliyat",e:"🛡️",k:["hushyorlik","qo‘ni-qo‘shni","xavfsizlik"],x:"Mas’uliyatli inson hushyor yashaydi; ogohlik bor joyda balo-ofatlar chekinadi."}]},
 q:[
 {t:"m",q:"Jaloliddin Rumiy kimdan qo‘rqishni uqtiradi?",a:["Befarq, loqayd odamdan","Kuchli raqibdan","Notanish sayyohdan","Qattiqqo‘l ustozdan"],e:"Loqayd odam o‘g‘ri va qotilga yo‘l qo‘yib beradi."},
 {t:"m",q:"«Besh narsa» hikmatiga ko‘ra, bemor bo‘lishdan avval nimani g‘animat bilish kerak?",a:["Sog‘liqni","Boylikni","Yoshlikni","Xotirjamlikni"],e:"«Bemor bo‘lishdan avval sog‘liqni»."},
 {t:"m",q:"Keksalikdan avval nimani g‘animat bilish kerak?",a:["Yoshlikni","Boylikni","Mansabni","Shuhratni"],e:"«Keksalikdan avval yoshlikni»."},
 {t:"m",q:"Lolaga otasi tug‘ilgan kunida nima sovg‘a qildi?",a:["Smartfon","Kompyuter","Soat","Velosiped"],e:"Zamonaviy smartfon sovg‘a qilgan, o‘sha kuniyoq u maktabga olib keldi."},
 {t:"m",q:"Guruhdagi o‘yindan so‘ng Lolada qanday o‘zgarish bo‘ldi?",a:["Kamgap va xafaqon bo‘lib qoldi","Sho‘x va xushchaqchaq bo‘ldi","A’lo baholarga o‘qiy boshladi","Sport bilan shug‘ullana ketdi"],e:"U kamgap, xafaqon va hafsalasiz qizga aylandi."},
 {t:"m",q:"Lolani xavfli topshiriqni bajarishdan kim to‘xtatib qoldi?",a:["Onasi","Otasi","Sinfdoshi","Qo‘shnisi"],e:"O‘zgarishlarni payqagan ona tongda uni bag‘riga bosdi."},
 {t:"m",q:"Ogohlik ta’rifiga qaysi xususiyat mos keladi?",a:["Voqealarga sinchkovlik bilan qarab, tahlil qilish","Har bir xabarga tekshirmasdan ishonib qo‘yish","Atrofdagi ishlarga umuman aralashmay yurish","Faqat o‘z huzur-halovatini o‘ylab yashash"],e:"Ogohlik – o‘ta e’tiborli, sinchkov munosabat va tahlil."},
 {t:"m",q:"«Ma’naviyat xazinasi»ga ko‘ra, ertasini o‘ylamay, bugungi huzur bilan yashaydiganlar qanday ataladi?",a:["G‘aflat uyqusidagilar","Orzu izdoshlari","Ilmli va fozil kishilar","Faol fuqarolar"],e:"Bunday insonlar g‘aflat uyqusidagilar deb ataladi."},
 {t:"tf",q:"Lolaning onasi qizidagi o‘zgarishlarni mutlaqo sezmagan.",a:false,e:"Aksincha, u o‘zgarishlarni payqab, ko‘z-quloq bo‘lib yurgan."},
 {t:"tf",q:"Mahmud Zamaxshariy hushyor odamni uzoqni yaqindek ko‘ra oladigan kishi deb ta’riflaydi.",a:true,e:"Uning fikr doirasi keng, g‘aflat uyqusidan yiroq bo‘ladi."},
 {t:"tf",q:"Darslikka ko‘ra, ogohlik va hushyorlik bor joyda balo-ofatlar chekinadi.",a:true,e:"Sezgirlik va sergaklik xavf-xatarni to‘xtatishga yordam beradi."},
 {t:"f",q:"Lolaning xatosi nimada edi va internetda qaysi qoidalarga amal qilish kerak?",e:"Notanish guruhga qo‘shilib, topshiriqlarni bajargan; notanishlarga ishonmaslik, shubhali o‘yindan chiqish, ota-onaga aytish kerak."}]},

{id:"m13",n:"15–16-mavzu",t:"Ko‘zga ko‘rinmas xatarlar",b:3,
 map:{c:"Ko‘rinmas xatarlar",br:[
  {t:"Internet asri",e:"🌐",k:["4,1 milliard","12,2 million","foyda"],x:"Darslikka ko‘ra dunyoda 4,1 milliard, O‘zbekistonda taxminan 12,2 million internet foydalanuvchisi bor."},
  {t:"Onlayn tahdid",e:"🕸️",k:["jaholat","ekstremizm","zo‘ravonlik"],x:"G‘araz niyatli kishilar qo‘lida internet buzg‘unchilik va axloqsizlik tarqatish quroliga aylanmoqda."},
  {t:"Mobil qulayligi",e:"📲",k:["aloqa","xavfsizlik","kamera, soat"],x:"Telefon tez aloqa, ota-ona bilan bog‘lanish va ko‘plab foydali vositalarni beradi."},
  {t:"Mobil zarari",e:"📵",k:["nurlanish","uyqu","qaramlik"],x:"Telefon nurlanishi salomatlik va uyquga zarar qiladi, bog‘lanib qolish tajovuzkorlik va qaramlikni kuchaytiradi."},
  {t:"Ilm va ixtiro",e:"💡",k:["Stiv Jobs","Apple","Al-Xorazmiy"],x:"Stiv Jobs 21 yoshida «Apple»ga asos soldi; yangi texnologiyalar rivojida Al-Xorazmiyning o‘chmas izi bor."}]},
 q:[
 {t:"m",q:"Darslikka ko‘ra, biz yashayotgan davr qanday atalmoqda?",a:["Internet asri","Kosmos asri","Bronza asri","Bug‘ asri"],e:"«Biz yashayotgan davr Internet asri deb atalmoqda»."},
 {t:"m",q:"Internetdagi tahdidlar asosan kimlarga qaratilgan?",a:["Bolalar va o‘smirlarga","Faqat olimlarga","Faqat nafaqadagi keksalarga","Faqat dehqonlarga"],e:"Foydalanuvchilarning asosiy qismi yoshlar bo‘lgani uchun."},
 {t:"m",q:"G‘arazli tashkilotlarning saytlari odatda qanday yo‘l tutadi?",a:["Mazmunini saqlab, nomini tez-tez yangilaydi","Nomini saqlab, mazmunini foydali qiladi","Faqat bir marta ochilib, abadiy yopiladi","O‘z maqsadini bosh sahifada ochiq yozadi"],e:"Ular to‘satdan paydo bo‘ladi va nomini tez-tez o‘zgartiradi."},
 {t:"m",q:"Yotishdan oldin uyali aloqa vositasini qayerga qo‘yish tavsiya etiladi?",a:["O‘rindan uzoqqa","Yostiq ostiga","Bosh yoniga","Ko‘rpa ichiga"],e:"Radioto‘lqinlar uyquga salbiy ta’sir qiladi."},
 {t:"m",q:"Mobil telefonning zararli to‘lqinini kamaytirish uchun qayerda gaplashgan ma’qul?",a:["Imkon qadar ochiq havoda","Yopiq va tor xonada","Chuqur yerto‘la ichida turib","Chaqaloq yonida"],e:"Ochiq havoda signal zo‘riqishsiz qabul qilinadi."},
 {t:"m",q:"Stiv Jobs necha yoshida «Apple» korporatsiyasiga asos solgan?",a:["21 yoshida","15 yoshida","30 yoshida","40 yoshida"],e:"Tajribasini oshirib, 21 yoshida asos solgan."},
 {t:"m",q:"Xalqaro telekanal boshlovchisi zamonaviy texnologiyalar rivojida kimning o‘chmas izi borligini aytdi?",a:["Al-Xorazmiyning","Al-Beruniyning","Ibn Sinoning","Mirzo Ulug‘bekning"],e:"Hujjatli film yakunida Al-Xorazmiydan minnatdor bo‘lish kerakligi aytiladi."},
 {t:"m",q:"Insoniyat uchun hozirgi eng katta xavf darslikda qanday ko‘rsatilgan?",a:["Ong va qalbni egallashga qaratilgan mafkuraviy kurash","Telefon quvvatining tez tugab qolishi va uzilishlar","Kompyuterlarning narxi yildan yilga qimmatlashishi","Elektron kitoblarning qog‘oz kitobdan ko‘payib ketishi"],e:"Eng katta xavf – insonlar ongi va qalbi uchun uzluksiz mafkuraviy kurash."},
 {t:"tf",q:"Internetning foydali jihatlari yo‘q, u faqat zarar keltiradi.",a:false,e:"Foydali jihatlari ko‘p, ammo g‘arazli kishilar undan yomon maqsadda foydalanishi mumkin."},
 {t:"tf",q:"Telefonni chaqaloqlar va yosh bolalarga yaqin tutmaslik tavsiya qilinadi.",a:true,e:"Nurlanish miya, ko‘rish va eshitish a’zolariga zarar yetkazadi."},
 {t:"tf",q:"Yomg‘ir va chaqmoq vaqtida ochiq joyda qo‘l telefonidan ko‘proq foydalanish kerak.",a:false,e:"Bunday paytda yopiq binolardan tashqarida telefondan foydalanmaslik kerak."},
 {t:"f",q:"Internetdan xavfsiz foydalanishning kamida uchta qoidasini yozing.",e:"Shaxsiy ma’lumotni tarqatmaslik, notanishlar bilan aloqaga kirishmaslik, shubhali saytlardan qochish, vaqtni me’yorlash, tahdid haqida kattalarga aytish."}]},

{id:"m14",n:"17–18-mavzu",t:"«Men qanday insonman?»",b:3,
 map:{c:"Men qanday insonman?",br:[
  {t:"O‘zini bilish",e:"🪞",k:["yutuq","kamchilik","savol"],x:"Ko‘pincha o‘zimizga kam savol beramiz; yutuq va kamchiliklarni aniqlash ularni tuzatishga yordam beradi."},
  {t:"Odatni almashtirish",e:"🔄",k:["qusur","yaxshi odat","reja"],x:"Va’dabozlik, vaqtni behuda o‘tkazish, yolg‘on kabi qusurlarni yaxshi odatga almashtirish kerak."},
  {t:"Riyodan saqlanish",e:"🎭",k:["xo‘jako‘rsin","samimiylik","har kuni"],x:"Faqat foyda bor joyda o‘zini madaniyatli ko‘rsatish – riyo. Chinakam muloyimlik har kunlik bo‘lishi kerak."},
  {t:"Qadriyatlar",e:"📜",k:["Avesto","ezgu fikr","yaxshilik"],x:"«Avesto»da ezgu fikr, ezgu so‘z va ezgu amal insoniy fazilat sifatida ulug‘lanadi."},
  {t:"Tilak va odob",e:"🙌",k:["yaxshi niyat","bemor","muborak"],x:"Safarga ketayotgan, qaytgan, bemor yoki yangilik qilgan kishiga mos yaxshi tilaklar bildiriladi."}]},
 q:[
 {t:"m",q:"Faqat foydasi bor joyda o‘zini madaniyatli qilib ko‘rsatish nima deyiladi?",a:["Riyo","Kamtarlik","Saxovat","Qanoat"],e:"Bu xo‘jako‘rsinga ish qilish – riyo."},
 {t:"m",q:"Chinakam muloyimlik darslikda nimaga o‘xshatiladi?",a:["Kundalik kiyim-boshga","Bayramona libosga","Qimmat taqinchoqqa","Mehmon dasturxoniga"],e:"U bayramona libos emas, har kuni orasta bo‘lishi kerak bo‘lgan kundalik kiyim."},
 {t:"m",q:"«Avesto»da qaysi fazilatlar ulug‘lanadi?",a:["Ezgu fikr, ezgu so‘z, ezgu amal","Kuch, boylik, yuqori martaba","Tez gapirish va bahsda yutish","Yolg‘izlik va mutlaq sukut"],e:"Ezgu fikr, ezgu so‘z va ezgu amal insoniy fazilat sifatida ulug‘lanadi."},
 {t:"m",q:"Safardan qaytgan kishiga qaysi tilak bildiriladi?",a:["«Ziyoratlar qabul bo‘lsin»","«Sog‘ayib keting»","«Qulluq bo‘lsin»","«Oy borib, omon qayting»"],e:"Javoban u «Murodingiz hosil bo‘lsin» deydi."},
 {t:"m",q:"Bemorni ko‘rgani qachon borish maqsadga muvofiq?",a:["Kunduz kuni","Yarim tunda","Tong saharda","Kech tunda"],e:"Darslikda kunduz kuni borish tavsiya etiladi."},
 {t:"m",q:"Kimdir yangi libos kiyganda qaysi ibora aytiladi?",a:["«Muborak bo‘lsin, yarashibdi»","«Safaringiz bexatar bo‘lsin»","«Tezroq sog‘ayib keting»","«Yaxshi dam olib keling»"],e:"Qulluq bo‘lsin, muborak bo‘lsin, yarashibdi, buyursin kabi iboralar qo‘llanadi."},
 {t:"m",q:"Mashg‘ulotda «Men qanday insonman?» savoliga javoblar nimaga yordam beradi?",a:["O‘z kamchiliklarini tuzatishga","Boshqalar aybini topishga","Sinfda baho talashishga","Do‘stlarni sinab ko‘rishga"],e:"Javoblar o‘zingizdagi kamchiliklarni tuzatishga yordam beradi."},
 {t:"m",q:"Maqsadsiz to‘planishga odatlangan 15 yoshli a’lochi bola oqibatda qanday bo‘lib qoldi?",a:["Qo‘pol va janjalkash","Yanada intizomli","Mashhur sportchi","Mehnatsevar hunarmand"],e:"U uyga kech qaytadigan, ota-onasiga qo‘pol, tengdoshlari bilan janjallashadigan bo‘ldi."},
 {t:"tf",q:"Hikoyadagi Umida onasining tilla zanjirini sotib yuborgan edi.",a:true,e:"U keyin tan olib, pulni qaytarib zanjirni olib kelishni taklif qildi."},
 {t:"tf",q:"Odob qoidalarini o‘zlashtirish va xarakter ustida ishlash muhim emas.",a:false,e:"O‘z ustida ishlash, odat va xarakter haqida o‘ylash zarur."},
 {t:"tf",q:"Ma’naviyat xazinasiga ko‘ra, e’tiborsiz qolgan kichik muammo bir kun hammaning katta muammosiga aylanadi.",a:true,e:"Shuning uchun befarq bo‘lmaslik kerak."},
 {t:"f",q:"Qaysi yomon odatingizdan xalos bo‘lmoqchisiz va uni nimaga almashtirasiz?",e:"Qusur va uning sababi aniqlanadi, o‘rniga qilinadigan yaxshi ish belgilanadi, natija va rag‘bat yoziladi."}]},

{id:"m15",n:"19-mavzu",t:"Muomala uchun zarur odoblar",b:4,
 map:{c:"Muomala odobi",br:[
  {t:"Begona mehmonlar",e:"🍽️",k:["Habibulla Qodiriy","non","dimog‘dor"],x:"Mehmon ayol nondan yemadi, iliq so‘z aytmadi va mezbonga dimog‘dor ko‘rindi."},
  {t:"Kibr sabablari",e:"👑",k:["boylik","ilm, martaba","husn"],x:"Habibulla Qodiriyning otasi: to‘rt narsa kishini kibr-havolantiradi – boylik, ilm, martaba va husn."},
  {t:"Mukammal odam",e:"🌟",k:["tavoze","halimlik","saxiylik"],x:"Donishmandga ko‘ra, imon mustahkamligi tavoze, halimlik, saxiylik va chiroyli xulqdan bilinadi."},
  {t:"Odob iboralari",e:"💬",k:["xush kelibsiz","xayrli tong","baraka toping"],x:"Xush kelibsiz, yaxshi boring, yoqimli ishtaha kabi so‘zlarni o‘z o‘rnida ishlatish kerak."},
  {t:"Til odobi",e:"👅",k:["yaxshi nutq","maqol","til jarohati"],x:"Xalq maqoli: «Yaxshi nutq asaldan shirinroq»."}]},
 q:[
 {t:"m",q:"«Begona mehmonlar» hikoyasining muallifi kim?",a:["Habibulla Qodiriy","Nosir Zohid","Abdulla Oripov","Erkin Vohidov"],e:"Hikoya Habibulla Qodiriy xotirasi."},
 {t:"m",q:"Mehmon ayol dasturxonga taklif qilinganda nima qildi?",a:["O‘tirmadi va nondan ham yemadi","Minnatdorchilik bilan duo qildi","Non yopishga yordamlashdi","Uzoq vaqt samimiy suhbat qurdi"],e:"U ikki og‘iz iliq so‘z ham aytmay, shiyponga qaytdi."},
 {t:"m",q:"Dadaning aytishicha, to‘rt narsa kishini nima qiladi?",a:["Kibr-havolantiradi","Mehribon qiladi","Sabrli qiladi","Kamtar qiladi"],e:"Boylik, ilm, martaba va husn kishini kibr-havolantirar ekan."},
 {t:"m",q:"Kibrga sabab bo‘luvchi to‘rtlikka qaysi biri kirmaydi?",a:["Sabr","Boylik","Martaba","Husn"],e:"To‘rtlik: boylik, ilm, martaba va husn."},
 {t:"m",q:"Donishmandning fikricha, qanday odam mukammal?",a:["Imoni mustahkam odam","Eng boy odam","Eng chiroyli odam","Eng baland mansabdor"],e:"«Imoni mustahkam odam – mukammaldir»."},
 {t:"m",q:"Donishmand insonning go‘zalligini nimada ko‘radi?",a:["Gap-so‘zi va odobida","Yuz tuzilishida","Kiyimining narxida","Uyining kattaligida"],e:"«Inson gap-so‘zi va odobi bilan xushsuratdir»."},
 {t:"m",q:"Ovqatlanayotgan kishiga qaysi so‘z mos?",a:["«Yoqimli ishtaha»","«Yaxshi yotib turing»","«Ko‘z tegmasin»","«Xayrli tong»"],e:"Har bir ibora o‘z o‘rnida ishlatiladi."},
 {t:"m",q:"Darslikdagi xalq maqoliga ko‘ra, yaxshi nutq nimadan shirinroq?",a:["Asaldan","Uzumdan","Shakardan","Qovundan"],e:"«Yaxshi nutq asaldan shirinroq»."},
 {t:"tf",q:"Oyisi mehmon ayolni juda kamtar va ochiqko‘ngil deb ta’riflagan.",a:false,e:"Oyisi: «Xotini juda dimog‘dor ko‘rinadi», degan."},
 {t:"tf",q:"Muomala insoniylikka xos yuksak xususiyat hisoblanadi.",a:true,e:"Donishmand rivoyati shunday xulosa bilan tugaydi."},
 {t:"tf",q:"«Xush kelibsiz» iborasi odatga aylantirish tavsiya etilgan so‘zlar qatorida bor.",a:true,e:"U ro‘yxatda birinchi bo‘lib berilgan."},
 {t:"f",q:"Sinfdoshingiz yordam so‘rasa va siz band bo‘lsangiz, odob bilan qanday javob berasiz?",e:"Qo‘pol gapirmasdan, uzr aytib sababini tushuntirish, imkon bo‘lganda yordam berishni taklif qilish kerak."}]},

{id:"m16",n:"20-mavzu",t:"Kommunikativlik – muvaffaqiyat kaliti",b:4,
 map:{c:"Kommunikativlik",br:[
  {t:"Tushuncha",e:"🤝",k:["muomala qobiliyati","yaqinlashish","munosabat"],x:"Kommunikativlik – to‘g‘ri muomala qila bilish, odamlar bilan samarali munosabat o‘rnatish qobiliyati."},
  {t:"Hisni boshqarish",e:"🧘",k:["aravakash","vazminlik","uzr"],x:"Aravakash xotirjam uzr so‘rab, g‘azablangan yigitni shashtidan tushirdi."},
  {t:"Ravon nutq",e:"🎤",k:["ovoz chiqarib o‘qish","ko‘zgu","tez aytish"],x:"Har kuni 15–20 daqiqa ovoz chiqarib o‘qish, ko‘zgu oldida mashq qilish nutqni ravon qiladi."},
  {t:"Suxandon maslahati",e:"📻",k:["samimiyat","tinglash","o‘ylab so‘zlash"],x:"A. O‘tbosarov: samimiy bo‘ling, ko‘proq tinglang, o‘ylang, keyin so‘zlang, juda tez gapirmang."},
  {t:"So‘z odobi",e:"📜",k:["Kaykovus","go‘zal so‘z","ko‘ngil"],x:"Kaykovus: bir fikrni bir ibora ko‘ngilni og‘ritadigan, boshqasi bahra beradigan qilib aytish mumkin."}]},
 q:[
 {t:"m",q:"Kommunikativlik nima?",a:["To‘g‘ri muomala qila bilish qobiliyati","Tez hisoblash va yodlash qobiliyati","Yolg‘iz ishlashni afzal ko‘rish odati","Texnikani ta’mirlay olish mahorati"],e:"Bu odamlar bilan yaqinlashish va samarali munosabat o‘rnata olish."},
 {t:"m",q:"Bozordagi voqeada kim hissiyotini boshqara oldi?",a:["Aravakash","Baqirgan yigit","Rasta sotuvchisi","Soqchi"],e:"Aravakash qayta-qayta vazminlik bilan uzr so‘radi."},
 {t:"m",q:"G‘azablangan yigitning shashtidan nima tushirdi?",a:["Aravakashning vazmin uzri va tabassumi","Atrofdagilarning baland baqiriqlari","Aravakashning qattiq javob qaytarishi","Aravadagi yukning yerga to‘kilishi"],e:"Aravakash vazminlik bilan uzr so‘rab, nim tabassum qildi."},
 {t:"m",q:"Nutqni ravon qilish uchun har kuni qancha vaqt ovoz chiqarib matn o‘qish tavsiya etiladi?",a:["15–20 daqiqa","1–2 daqiqa","3–4 soat","5–6 soat"],e:"Har kuni 15–20 daqiqa o‘qish so‘zlarni aniq aytishga yordam beradi."},
 {t:"m",q:"Ko‘zgu qarshisida mashq qilish nimani o‘rganishga yordam beradi?",a:["Yuz ifodasi va qad-qomatni tutishni","Misollarni tez hisoblashni","Chiroyli husnixat bilan yozishni","Chet tilidan tarjima qilishni"],e:"Hislarni yuzda ifodalash, tana harakati va qad-qomat o‘rganiladi."},
 {t:"m",q:"Suxandon Abdumo‘min O‘tbosarov maslahatlariga qaysi biri kiradi?",a:["O‘ylang, keyin so‘zlang","Imkon qadar tez gapiring","Faqat o‘zingiz gapiring","Ko‘p ortiqcha axborot bering"],e:"U o‘ylab gapirish, ko‘proq tinglash va juda tez gapirmaslikni aytadi."},
 {t:"m",q:"O‘g‘liga xalq oldidagi so‘zing go‘zal bo‘lsin deb nasihat qilgan kim?",a:["Kaykovus","Konfutsiy","Sofokl","Binoiy"],e:"Kaykovus nasihatida har kishining ahvoli so‘zi ostida yashiringani aytiladi."},
 {t:"m",q:"Jasmina hashardan oldin Azizdan farqli nima qildi?",a:["Yig‘ilish o‘tkazib, sinfdoshlar fikrini so‘radi","Topshiriqni so‘ramasdan buyruq qilib berdi","Hamma ishni o‘zi yolg‘iz bajarmoqchi bo‘ldi","Hasharni sinfdoshlarga aytmay bekor qildi"],e:"Jasmina fikr so‘radi, Aziz esa faqat topshiriq berdi."},
 {t:"tf",q:"Rahbar va tadbirkorlarning muomala qobiliyati ularning muvaffaqiyatiga sabab bo‘ladi.",a:true,e:"Darslikda kommunikativlik shunday baholangan."},
 {t:"tf",q:"Muzokarada ravon nutq va fikrni aniq ifodalashning ahamiyati yo‘q.",a:false,e:"Aksincha, bu eng muhimi."},
 {t:"tf",q:"Suxandon maslahatiga ko‘ra, juda tez gapirmaslik kerak.",a:true,e:"«Juda tez gapirmang» – ro‘yxatdagi maslahat."},
 {t:"f",q:"Nutqingizni rivojlantirish uchun qaysi mashqlarni bajarasiz?",e:"Ovoz chiqarib o‘qish, ko‘zgu oldida gapirish, fikrni yozish, tez aytish, tovushlarni to‘g‘ri talaffuz qilish, ko‘proq tinglash."}]},

{id:"m17",n:"21–22-mavzu",t:"Samarali muloqot sirlari",b:4,
 map:{c:"Samarali muloqot",br:[
  {t:"Maqsad va tinglash",e:"👂",k:["nima xohlaysiz","tinglash","savol"],x:"Avval nima xohlayotganingizni aniqlang, boshqalar fikrini tinglang va savol bering."},
  {t:"Samimiyat",e:"👀",k:["e’tibor","ko‘z aloqasi","xayrixohlik"],x:"Samimiy bo‘ling, suhbatdosh ko‘ziga qarang, telefon bilan chalg‘imang."},
  {t:"Ota-ona va qo‘shni",e:"👪",k:["past ovoz","ochiq yuz","minnat qilmaslik"],x:"Ota-onaga baland ovozda gapirmaslik, qo‘shniga ochiq yuz va mehribonlik bilan muomala qilish."},
  {t:"Jamoat transporti",e:"🚌",k:["joy berish","ovozsiz rejim","yo‘l haqi"],x:"Keksa, yosh bolali, nogiron va homiladorlarga joy berish, telefonni ovozsiz qilish kerak."},
  {t:"Teatr va kutubxona",e:"🎭",k:["vaqtida kelish","jimlik","kitobni asrash"],x:"Spektaklga 15–20 daqiqa oldin keling; kutubxonada xalaqit bermang, kitobni buklamang."}]},
 q:[
 {t:"m",q:"Samarali muloqotning birinchi qoidasi qaysi?",a:["Nima xohlayotganingizni aniqlash","Suhbatni bahsdan boshlash","Telefonni qo‘lga olib turish","Ko‘proq o‘zingizni maqtash"],e:"Nima demoqchisiz va qanday javob kutyapsiz – shu aniqlanadi."},
 {t:"m",q:"Suhbat davomida savol berish nimadan darak?",a:["Mavzuga qiziqishdan","Suhbatdan zerikishdan","Suhbatdoshga ishonmaslikdan","Tezroq ketish istagidan"],e:"Savol berish mavzuga qiziqishingizni ko‘rsatadi."},
 {t:"m",q:"Suhbat paytida qaysi holat katta beodoblik sanaladi?",a:["Qo‘l telefonidan ko‘z uzmaslik","Suhbatdoshning ko‘ziga qarab gaplashish","Bosh irg‘ab tasdiqlash","Aniqlovchi savol berish"],e:"Bu suhbatdoshga e’tiborsizlik."},
 {t:"m",q:"Ota-ona chaqirganda nima qilish kerak?",a:["Tezda javob berish","Ishni tugatib, keyin javob berish","Eshitmaganga olish","Baland ovozda e’tiroz bildirish"],e:"«Ota-onangiz chaqirsalar, tezda javob bering»."},
 {t:"m",q:"Qo‘shnining hojatini chiqarganda nima qilmaslik kerak?",a:["Minnat qilmaslik","Salomlashmaslik","Tabassum qilmaslik","Holini so‘ramaslik"],e:"Yordam beminnat bo‘lishi kerak."},
 {t:"m",q:"Spektakl boshlanishidan qancha oldin kelishga odatlanish tavsiya etiladi?",a:["15–20 daqiqa oldin","2–3 soat oldin","Aynan boshlanganda","Bir kun oldin"],e:"Teatr odobi shunday."},
 {t:"m",q:"Kutubxonada kitob bilan qanday muomala qilinadi?",a:["Ehtiyotlab varaqlab, buklamaslik","Kerakli betni yirtib olish","Sahifa chetiga qalam bilan izoh yozish","Betini buklab belgi qo‘yish"],e:"Kitobdan ko‘pchilik foydalanadi."},
 {t:"m",q:"Transportda birinchi navbatda kimlarga joy berish kerak?",a:["Keksa, yosh bolali, nogiron va homiladorlarga","Yonida turgan tanish va sinfdosh do‘stlarga","Eng oldin so‘ragan har qanday tengdoshga","Katta sumka ko‘tarib olgan istalgan o‘smirga"],e:"Darslikda aynan shu toifalar sanalgan."},
 {t:"tf",q:"Jamoat transportida ovqat yeyish odobga to‘g‘ri keladi.",a:false,e:"Jamoat transportida ovqat yeyish mutlaqo mumkin emas."},
 {t:"tf",q:"«Tig‘ jarohati bitar, til jarohati bitmas» maqoli muloqotda so‘zga ehtiyot bo‘lishga chaqiradi.",a:true,e:"Qo‘pol so‘z uzoq vaqt og‘riq beradi."},
 {t:"tf",q:"Samarali muloqot uchun gapirishdan oldin boshqalarning fikrini tinglash kerak.",a:true,e:"Tinglash ikki tomonlama tushunish asosi."},
 {t:"f",q:"Sizga xafa bo‘lgan do‘stingiz bilan suhbatni qanday olib borasiz?",e:"Samimiy va e’tiborli bo‘lish, tinglash, savol berish, ko‘zga qarab tasdiqlash, xayrixohlik bildirish, telefonni chetga qo‘yish."}]},

{id:"m18",n:"23–24-mavzu",t:"Farzand – oila ko‘zgusi",b:4,
 map:{c:"Farzand – oila ko‘zgusi",br:[
  {t:"Oiladagi tarbiya",e:"🏠",k:["Malika","onasining nasihati","saxiylik"],x:"Onasining «hammaning ham qurbi yetmaydi» degan gapini eslagan Malika ko‘ylagini sovg‘a qilgisi keldi."},
  {t:"Inoq oila",e:"👨‍👩‍👧‍👦",k:["sabrlilik","kechirimlilik","muhabbat"],x:"Xitoylik katta oilaning baxt siri: sabrlilik, kechirimlilik va muhabbat."},
  {t:"Ota va o‘g‘il",e:"🎓",k:["dehqon ota","rag‘bat","mas’uliyat"],x:"Dehqon ota o‘g‘lidan o‘rganganlarini o‘ziga o‘rgatishni so‘radi, har kuni tingladi va rag‘batlantirdi."},
  {t:"Xulq",e:"📘",k:["oila","mahalla","yoqimli harakat"],x:"Xulq – oila, jamoa, mahalla miqyosida ahamiyatli bo‘lgan yoqimli xatti-harakatlar majmui."},
  {t:"Forobiy o‘giti",e:"🛠️",k:["kasb-kor","tarbiya","fazilat"],x:"Forobiy: har kishi kasb-korni mukammal bilishi, yaxshi tarbiya va xulq-odobga ega bo‘lishi kerak."}]},
 q:[
 {t:"m",q:"Yangi ko‘ylak oldirgan Malikani onasi nega koyidi?",a:["Faqat o‘zini o‘ylagani uchun","Maktabga kech qolgani uchun","Ko‘ylagini yirtgani uchun","Kitob o‘qimagani uchun"],e:"Ona hammaning ham bunday kiyim kiyishga qurbi yetmasligini aytdi."},
 {t:"m",q:"O‘rindiqqa o‘tirgan qiz qanday kitob o‘qiyotgan edi?",a:["Chin insoniylik haqida","Uzoq sayohatlar haqida","Texnika ixtirolari haqida","Sport rekordlari haqida"],e:"Qiz «Chin insoniylik haqida» deb javob berdi."},
 {t:"m",q:"Xitoylik inoq oila haqidagi qog‘ozga qaysi uch so‘z yozilgan edi?",a:["Sabrlilik, kechirimlilik, muhabbat","Boylik, shuhrat, martaba","Qattiq intizom, qo‘rquv, so‘zsiz itoat","Ilm, savdo, hunarmandlik"],e:"Bu har qanday baxtli oila va yurt tinchligining asosi."},
 {t:"m",q:"Oqsoqol fikricha, o‘sha uch so‘z yana nimaning asosi?",a:["Yurt tinchligining","Savdo foydasining","Harbiy g‘alabaning","Sayohat zavqining"],e:"«Yurt tinchligining asosi ham shu»."},
 {t:"m",q:"Nufuzli universitetga yuqori natija bilan kirgan yigitning otasi kim edi?",a:["Chekka qishloqdagi dehqon","Universitetning mashhur professori","Boy savdogar","Maktab direktori"],e:"Uning maxsus ma’lumoti va qo‘shimcha darsga puli bo‘lmagan."},
 {t:"m",q:"Ota maktabga birinchi borgan o‘g‘lidan nima so‘radi?",a:["O‘rganganini otasiga ham o‘rgatishni","Har kuni faqat olgan baholarini aytib turishni","Darsdan so‘ng dalada ishlashni","Tezroq hunar o‘rganib chiqishni"],e:"Shu tariqa o‘g‘il otaga ustozlik qildi."},
 {t:"m",q:"Ota kechqurunlari nima qilardi?",a:["Birga dars qilib, o‘g‘lini rag‘batlantirardi","Yollangan qo‘shimcha o‘qituvchini kutib olardi","O‘g‘lini yolg‘iz qoldirib ketardi","Daftarlarini ko‘rmay uxlardi"],e:"O‘g‘lini tinglash va rag‘batlantirish kundalik mashg‘ulotiga aylangan."},
 {t:"m",q:"Har kishi kasb-korni mukammal bilishi va yaxshi tarbiya olishi kerakligini kim aytgan?",a:["Abu Nasr Forobiy","Abu Ali ibn Sino","Alisher Navoiy","Mahmud Zamaxshariy"],e:"Bu Forobiy hikmati."},
 {t:"tf",q:"Yigitning otasi o‘g‘liga qimmat qo‘shimcha darslar yollab bergan.",a:false,e:"Uning bunga qurbi yetmagan."},
 {t:"tf",q:"Xitoylik katta oila yashagan qishloqda qariyalar xotirjam, bolalar baxtli edi.",a:true,e:"Oila a’zolari nihoyatda ahil va inoq yashagan."},
 {t:"tf",q:"Mavzuda odobli, bilimdon va mehnatsevar farzand ota-ona hamda jamiyat boyligi sifatida ta’riflanadi.",a:true,e:"Savollarda aynan shu fikr keltirilgan."},
 {t:"f",q:"Nima uchun «Farzand – oila ko‘zgusi» deyiladi? Misol keltiring.",e:"Farzand xulqida oiladagi tarbiyaviy muhit aks etadi: masalan, Malika onasining nasihati ta’sirida saxiylik qilmoqchi bo‘ldi."}]},

{id:"m19",n:"25-mavzu",t:"Avval tinglashni o‘rganing",b:4,
 map:{c:"Tinglash",br:[
  {t:"Buzuq telefon",e:"☎️",k:["zanjir","eslab qolish","taqqoslash"],x:"O‘yinda matn ishtirokchidan ishtirokchiga yashirin aytiladi va oxirida asl matn bilan solishtiriladi."},
  {t:"Tinglash odobi",e:"👂",k:["e’tibor","xushmuomalalik","xulq"],x:"E’tibor bilan tinglash xushmuomalalik va yaxshi xulqni aks ettiradi."},
  {t:"Bilim manbai",e:"🎒",k:["o‘qituvchi","diqqat","malaka"],x:"O‘qituvchi ko‘rsatmalariga diqqat bilan quloq solish bilim va malakani oshiradi."},
  {t:"Munosabatlar",e:"💬",k:["suhbat","salbiy ta’sir","san’at"],x:"E’tiborsiz tinglash munosabatlarga zarar qiladi; tinglash – san’at."},
  {t:"Navoiy o‘giti",e:"🔥",k:["olov","foyda","ehtiyotkorlik"],x:"Navoiy: odamlar bilan olovga muomala qilgandek bo‘l – foydasini ol, kuydirishidan ehtiyot bo‘l."}]},
 q:[
 {t:"m",q:"«Buzuq telefon» o‘yinida ma’lumot keyingi ishtirokchiga qanday yetkaziladi?",a:["Eslab qolib, boshqalarga eshittirmay aytiladi","Qog‘ozga ko‘chirilib, hammaga tarqatiladi","Doskaga yozilib, birgalikda o‘qiladi","Telefonda xabar qilib yuboriladi"],e:"Har bir ishtirokchi matnni eslab qolib, navbatdagisiga aytadi."},
 {t:"m",q:"O‘yin oxirida oxirgi ishtirokchining matni nima bilan solishtiriladi?",a:["Birinchi o‘qilgan asl matn bilan","Darslikdagi boshqa she’r bilan","O‘qituvchining daftari bilan","Boshqa sinf hikoyasi bilan"],e:"Farq chiqsa, jamoa yutqazadi."},
 {t:"m",q:"E’tibor bilan tinglash nimani aks ettiradi?",a:["Xushmuomalalik va yaxshi xulqni","Zerikish va befarqlikni","Bilimsizlik va ojizlikni","Shoshqaloqlik va asabiylikni"],e:"«Bilasizmi?» ruknidagi birinchi fikr."},
 {t:"m",q:"O‘qituvchi ko‘rsatmalariga diqqat bilan quloq solish nimani oshiradi?",a:["Bilim va malakani","Tushunmovchilikni","Dars vaqtini","Uy vazifasini"],e:"Diqqat bilim va malakani oshiradi."},
 {t:"m",q:"E’tiborsiz tinglash nimaga salbiy ta’sir qiladi?",a:["Ijtimoiy munosabatlarga","Ob-havo o‘zgarishiga","Bino mustahkamligiga","Ko‘cha harakati tezligiga"],e:"E’tiborsizlik natijasi munosabatlarni buzadi."},
 {t:"m",q:"Boshqalarni tinglash darslikda nima deb hisoblanadi?",a:["San’at","Majburiyatdan qochish","Vaqt isrofi","Ojizlik"],e:"«Boshqalarni tinglash ham san’at hisoblanadi»."},
 {t:"m",q:"Navoiy odamlar bilan nimaga muomala qilgandek munosabatda bo‘lishni maslahat bergan?",a:["Olovga","Suvga","Shamolga","Toshga"],e:"Foydasidan olib, kuydirishidan ehtiyot bo‘lish kerak."},
 {t:"m",q:"Tinglash qobiliyati nimani yaxshilashi mumkin?",a:["Munosabatlar va suhbatni","Yugurish tezligini","Husnixat chiroyini","Ko‘rish o‘tkirligini"],e:"Tinglash ijtimoiy munosabat va suhbatni yaxshilaydi."},
 {t:"tf",q:"«Buzuq telefon» o‘yinida 1-ishtirokchi avvaldan tayyorlangan, boshqalarga noma’lum matnni o‘qiydi.",a:true,e:"O‘yin qoidasi shunday."},
 {t:"tf",q:"O‘yinda matn eshitilishi uchun barcha ishtirokchilar bir xonada birga turadi.",a:false,e:"Ishtirokchilar xonadan chiqadi, aytilganni boshqalar eshitmasligi kerak."},
 {t:"tf",q:"Tinglash qobiliyati suhbatni yaxshilashga yordam bermaydi.",a:false,e:"Aksincha, u suhbat va munosabatni yaxshilashi mumkin."},
 {t:"f",q:"Uchrashgan do‘stlar suhbatlashish o‘rniga smartfonga qarab o‘tirsa, bu holatni qanday baholaysiz?",e:"Bu bir-biriga e’tiborsizlik, muloqot va do‘stlikka zarar; telefonni chetga qo‘yib, diqqat bilan tinglash kerak."}]},

{id:"m20",n:"26-mavzu",t:"Harakat qilmagan baxtga yetolmas",b:4,
 map:{c:"Harakat va baxt",br:[
  {t:"Tokzordagi oltin",e:"🍇",k:["dehqon","ketmon","mo‘l hosil"],x:"O‘g‘il oltin qidirib tok tagini kovladi, mo‘l hosildan boyidi: ota mehnatdan unadigan oltinni aytgan edi."},
  {t:"Binoiy va Sofokl",e:"📜",k:["barakat","harakat","yaxshi hayot"],x:"Binoiy: harakatga qarab barakat topiladi. Sofokl: yaxshi hayot harakat bilan hisoblashadi."},
  {t:"Ishtiyoq",e:"🔥",k:["imkoniyat","g‘oya","o‘zgartirish"],x:"Hayot – imkoniyat. Dunyoni yaxshi tomonga o‘zgartirish ishtiyoqi bilan yashang."},
  {t:"Dadillik",e:"🚀",k:["tavakkal","ishonch","muvaffaqiyatsizlik"],x:"Ko‘z qo‘rqoq, qo‘l botir. Muvaffaqiyatsizlikdan saboq olib, ortga chekinmang."},
  {t:"Hamjihatlik",e:"🤝",k:["ko‘zi ojiz","oyog‘i falaj","do‘stlik"],x:"Biri yo‘l ko‘rsatib, biri yurib, ikkalasi halokatdan qutuldi."}]},
 q:[
 {t:"m",q:"Dehqon otasi o‘g‘liga oltin qayerga ko‘milganini aytdi?",a:["Toklarning tagiga","Uy devoriga","Quduq yoniga","Ombor ostiga"],e:"Toklar tagida ikki xum tilla borligini aytgan."},
 {t:"m",q:"O‘g‘il tillani yilda qachon kovlab olishi kerak edi?",a:["Bahor va kuzda","Yoz va qishda","Faqat qishda","Har oy boshida"],e:"Yilda ikki marta – bahor va kuzda."},
 {t:"m",q:"Ota aytgan «oltin» aslida nima edi?",a:["Mehnatdan unadigan boylik","Yerga yashirilgan tangalar","Qo‘shnidan qolgan qarz","Qadimiy zargarlik buyumi"],e:"Tok tagini yumshatish mo‘l hosil va boylik keltirdi."},
 {t:"m",q:"Yigitga ota nasihatining mazmunini kim tushuntirdi?",a:["Otasining qadrdon oshnasi","Mahalladagi keksa savdogar","Qishloq hakimi","Yosh qo‘shnisi"],e:"Chol: «Otang aytgan oltinlarni olibsan-ku», dedi."},
 {t:"m",q:"«Yaxshi hayot harakat bilan hisoblashadi» degan fikr kimniki?",a:["Sofokl","Arastu","Konfutsiy","Binoiy"],e:"Qadimgi yunon donishmandi Sofokl."},
 {t:"m",q:"Mavzuga ko‘ra, muvaffaqiyatsizlikka qanday qarash kerak?",a:["Undan saboq olib, oldinga intilish","Darhol qo‘yilgan maqsaddan voz kechish","Aybni boshqalarga to‘nkash","Qayta urinishdan qo‘rqish"],e:"U maqsad sari bir qadam siljitadi, ortga chekinmaslik kerak."},
 {t:"m",q:"Cho‘ldagi qishloqda qolgan ikki kishi qanday qutuldi?",a:["Ko‘zi ojiz falajni opichlab, falaj yo‘l ko‘rsatdi","Karvon kelib, ikkalasini aravada olib ketdi","Har biri alohida yo‘lga chiqib, o‘z uyini mustaqil topdi","Qishloqda yordam kelguncha kutib o‘tirishdi"],e:"Bir-birining kamchiligini to‘ldirib, halokatdan qutulishdi."},
 {t:"m",q:"«Ilmli kishi xazina bo‘lsa, ... uning kalitidir» hikmatini to‘ldiring.",a:["savol","sukut","boylik","uyqu"],e:"«Ilmli kishi xazina bo‘lsa, savol uning kalitidir»."},
 {t:"tf",q:"Yigit tok tagidan ikki xum tilla topib oldi.",a:false,e:"Oltin topilmadi, ammo tok mo‘l hosil berdi."},
 {t:"tf",q:"Qutulgan ko‘zi ojiz va oyog‘i falaj keyin qalin do‘st bo‘lib qolishdi.",a:true,e:"Ular bir-biridan ajralmaydigan do‘st bo‘lishdi."},
 {t:"tf",q:"Maslahatlardan biri – ezgu istaklarni maqsadga aylantirib, orzulardan voz kechmaslik.",a:true,e:"Munosib hayot maqsadlarini ro‘yobga chiqarganlarga nasib etadi."},
 {t:"f",q:"Dehqon hikoyasidan qanday xulosa chiqardingiz?",e:"Boylik va baxt tayyor topilmaydi, mehnat va harakat bilan qo‘lga kiritiladi."}]},

{id:"m21",n:"27–28-mavzu",t:"Yaxshilik yo‘lida hamkorlik",b:5,
 map:{c:"Hamkorlik",br:[
  {t:"Pufaklar sabog‘i",e:"🎈",k:["40 xodim","ulashish","unumdorlik"],x:"Har kim o‘z pufagini qidirganda topolmadi, bir-biriga uzatganda esa tez topdi."},
  {t:"Hamkorlik qoidalari",e:"📋",k:["ishonch","fikrni hurmat","qo‘llab-quvvatlash"],x:"Ishonchni yo‘qotmaslik, o‘zgalar fikri va mahoratini hurmat qilish, og‘ir paytda qo‘llash."},
  {t:"Jamoa kuchi",e:"👥",k:["bir kishi","jamoa","hamma uchun"],x:"Bir nafar kishi jamoa bo‘la olmaydi. «Hamma bir kishi uchun, bir kishi hamma uchun»."},
  {t:"Turnalar",e:"🕊️",k:["burchak shakli","yetakchi almashadi","quv-quv"],x:"Turnalar burchak shaklida uchib kuchni tejaydi, charchagan yetakchi orqaga o‘tadi."},
  {t:"Jipslik",e:"🔺",k:["Bermud o‘yini","an’ana","ahillik"],x:"O‘yin va umumiy mehnat sinf jamoasini mustahkamlaydi."}]},
 q:[
 {t:"m",q:"Hikoyadagi kompaniyaning daromadi nega tushib ketdi?",a:["Xodimlar ma’lumot yashirib, hamkorlik qilmadi","Xodimlarning hammasi tajribasiz keksalar edi","Rahbar har kuni bayram uyushtirib turdi","Kompaniyada atigi ikki kishi ishlar edi"],e:"40 xodim yosh va aqlli edi, ammo hamkorlik qilmasdi."},
 {t:"m",q:"Xodimlar o‘z ismi yozilgan pufakni qachon tez topishdi?",a:["Topgan pufagini egasiga uzatganda","Har kim yolg‘iz qidirganda","Ortiqcha pufaklarni yorib tashlaganda","Rahbar o‘zi ulashib berganda"],e:"Pufaklar qo‘lma-qo‘l bo‘lib, sanoqli daqiqada egasini topdi."},
 {t:"m",q:"Kompaniya rahbari o‘yin orqali nimani ko‘rsatdi?",a:["Birga ishlash unumdorlikni oshirishini","Raqobat har doim eng foydaliligini","Yolg‘iz ishlash qulayroq ekanini","Bayram ishdan muhimroq ekanini"],e:"Borini baham ko‘rib birga ishlasak, muammolar hal bo‘ladi."},
 {t:"m",q:"Turnalar qanday shaklda tizilib uchadi?",a:["Burchak shaklida","Doira shaklida","To‘rtburchak shaklida","Tartibsiz to‘da bo‘lib"],e:"Bu shaklda samaradorlik oshadi."},
 {t:"m",q:"Yetakchi turna charchasa nima bo‘ladi?",a:["Oxirga o‘tadi, boshqasi yetakchilik qiladi","To‘dadan chiqib, yolg‘iz uchib ketadi","Butun to‘da uchishni abadiy to‘xtatadi","U charchasa ham oldinda qolaveradi"],e:"Yetakchilik navbat bilan almashadi."},
 {t:"m",q:"Turnalarning «quv-quv» ovozi nima uchun kerak?",a:["Bir-birini qo‘llab, tezlikni saqlash uchun","Boshqa qushlarni qo‘rqitib haydash uchun","Yetakchini to‘dadan chiqarib yuborish uchun","Yerga qo‘nishni darhol talab qilish uchun"],e:"Ovoz bilan qo‘llab-quvvatlab, tezlikni bir xil saqlaydi."},
 {t:"m",q:"Hamkorlikda ishlash uchun nima qilish kerak?",a:["O‘zgalar fikrini hurmat qilish","Mayda ishlarni mensimaslik","Ma’lumotni yashirib yurish","Faqat o‘zini maqtab turish"],e:"O‘zaro ishonch, hurmat va qo‘llab-quvvatlash kerak."},
 {t:"m",q:"Mavzudagi jamoa qoidasi qaysi?",a:["«Hamma bir kishi uchun, bir kishi hamma uchun»","«Har kim faqat o‘z ishi uchun javob beradi»","«Kuchli bo‘lgan yolg‘iz o‘zi g‘olib chiqadi»","«Boshqaning ishiga hech qachon aralashma»"],e:"Bu hamkorlik qoidalari ichida keltirilgan."},
 {t:"tf",q:"Birinchi urinishda hamma xodim belgilangan vaqtda o‘z pufagini topdi.",a:false,e:"Hech kim topa olmadi."},
 {t:"tf",q:"Darslikka ko‘ra, katta ishlar kichik ishlardan hosil bo‘ladi, shuning uchun kichik ishga ham e’tibor kerak.",a:true,e:"Hamkorlik qoidalaridan biri."},
 {t:"tf",q:"«Ma’naviyat xazinasi»ga ko‘ra, bir nafar kishining o‘zi jamoa bo‘la oladi.",a:false,e:"Odam jamoaning muhim qismi bo‘lishi mumkin, lekin yolg‘iz jamoa emas."},
 {t:"f",q:"Turnalar parvozidan sinf jamoasi nimani o‘rganishi mumkin?",e:"Bitta yo‘nalishda birga harakat qilish, bir-birini qo‘llash, yetakchilik va yukni navbat bilan bo‘lishish."}]},

{id:"m22",n:"29-mavzu",t:"Do‘stlik",b:5,
 map:{c:"Do‘stlik",br:[
  {t:"Do‘stlik qoidalari",e:"📝",k:["guruhda ishlash","muhokama","10 qoida"],x:"O‘quvchilar o‘z qoidalarini yozib, bosqichma-bosqich muhokama qiladi va 10 ta qoidaga birlashtiradi."},
  {t:"Do‘stlik lafzi",e:"🎖️",k:["Qurbonboy","Nikolay","ont"],x:"Qurbonboy urushda halok bo‘lgan tutingan inisi Nikolayning nomini olib, ontiga sodiq qoldi."},
  {t:"Do‘st – oyna",e:"🪞",k:["Ibn Sino","yaxshi tomon","kamchilik"],x:"Ibn Sino: yaxshi do‘st oynadir, unda kishining yaxshi va yomon tomonlari aks etadi."},
  {t:"Yaxshi do‘st bo‘lish",e:"💛",k:["samimiyat","tinglash","vaqt ajratish"],x:"Samimiy bo‘ling, yolg‘on gapirmang, tinglang, vaqt ajrating, qo‘llab-quvvatlang."},
  {t:"Baham ko‘rish",e:"🤗",k:["Erkin Vohidov","shodlik","g‘am"],x:"Do‘st bilan baham ko‘rilsa, shodlik ko‘payadi, g‘am esa bo‘linadi."}]},
 q:[
 {t:"m",q:"«Do‘stlik lafzi»dagi Nikolay otaning avvalgi ismi nima edi?",a:["Qurbonboy","Sulaymon","Olimjon","Bahodir"],e:"Qishloqda uni Qurbonboy chavandoz deyishardi."},
 {t:"m",q:"Nikolay ota qaysi tumanda yashaydi?",a:["Ellikqal’a","To‘rtko‘l","Asaka","Chust"],e:"Qoraqalpog‘istonning Ellikqal’a tumanida."},
 {t:"m",q:"Mina portlaganda Qurbonboy do‘stiga qanday yordam berdi?",a:["Tuproqdan chiqarib, bo‘linmaga ko‘tarib bordi","O‘zi qochib, keyin boshqalarga xabar berdi","Uni o‘ra ichida qoldirib, jangga kirdi","Shifokor kelguncha chetdan kutib o‘tirdi"],e:"Ikki chaqirim olisdagi bo‘linmaga ko‘tarib olib keldi."},
 {t:"m",q:"Ikki do‘st qanday ont ichdi?",a:["Tirik qolgani halok bo‘lganning nomini olishga","Urushdan keyin bir shaharda savdo qilishga","Hech qachon qishlog‘iga qaytib bormaslikka","Medallarini o‘zaro almashtirib taqishga"],e:"Halok bo‘lgan inisining nomini olishga ont ichishdi."},
 {t:"m",q:"«Yaxshi do‘st oynadir» hikmati kimniki?",a:["Abu Ali ibn Sino","Alisher Navoiy","Erkin Vohidov","Abu Nasr Forobiy"],e:"Unda kishining yaxshi va yomon tomonlari aks etadi."},
 {t:"m",q:"«Agar do‘sting bilan teng ko‘rsang baham, shodlik teng ko‘payar, teng bo‘linar g‘am» satrlari kimniki?",a:["Erkin Vohidov","Abdulla Oripov","Abdulla Avloniy","Habibulla Qodiriy"],e:"Shoir Erkin Vohidovning do‘stlik haqidagi fikri."},
 {t:"m",q:"Yaxshi do‘st bo‘lish qoidalariga qaysi biri kiradi?",a:["Do‘stga vaqt ajratish","Do‘stdan sir yashirib aldash","Faqat foyda bo‘lganda yo‘qlash","Gapini oxirigacha eshitmaslik"],e:"Samimiylik, tinglash, vaqt ajratish va qo‘llab-quvvatlash."},
 {t:"m",q:"«Ma’naviyat xazinasidan»da do‘stlik nimadan afzal deyilgan?",a:["Barcha boylikdan","Barcha ilmdan","Barcha hunardan","Barcha sayohatdan"],e:"«Do‘stlik – barcha boylikdan afzal»."},
 {t:"tf",q:"Qurbonboy urushdan qaytgach, o‘zini Nikolay deb chaqirishlarini talab qildi.",a:true,e:"U do‘stiga bergan ontiga sodiq qoldi."},
 {t:"tf",q:"Qishloqdoshlar voqeani eshitgandan keyin ham uning qaroriga qarshi turishdi.",a:false,e:"Avval hayron bo‘lishdi, voqeani eshitgach qo‘llab-quvvatladilar."},
 {t:"tf",q:"Yaxshi do‘st bo‘lish qoidalarida yolg‘on gapirmaslik tavsiya etiladi.",a:true,e:"«Yolg‘on gapirmang» – qoidalardan biri."},
 {t:"f",q:"Chin do‘stingizning qaysi fazilatlari sizga yoqadi va siz qanday do‘stsiz?",e:"Samimiylik, rostgo‘ylik, tinglash, qo‘llab-quvvatlash, so‘zida turish kabi fazilatlar misollar bilan yoziladi."}]},

{id:"m23",n:"30-mavzu",t:"Insoniylik – xalqimizning eng buyuk fazilati",b:5,
 map:{c:"Insoniylik",br:[
  {t:"Temur va ruboiy",e:"📜",k:["ming tanga","qalandar","yaxshi nom"],x:"Yosh Temur qo‘y pulini ruboiyga berdi; otasi uni ezgu sarf deb baholadi."},
  {t:"Ezgu nom",e:"🌟",k:["Kamol Xo‘jandiy","zulm","yaxshilik"],x:"Ruboiy mazmuni: zulm bilan nom qoldirib bo‘lmaydi, dunyoda yaxshilik bilan nom qoldir."},
  {t:"Volontyor",e:"🙋",k:["ixtiyoriy","beminnat","beg‘araz"],x:"Volontyor – ixtiyoriy, beminnat, beg‘araz ijtimoiy foydali faoliyat yurituvchi shaxs."},
  {t:"Volontyorlik qonuni",e:"⚖️",k:["2019-yil","2-dekabr","maqsad va vazifa"],x:"«Volontyorlik faoliyati to‘g‘risida»gi Qonun 2019-yil 2-dekabrda qabul qilingan."},
  {t:"Illatlardan saqlanish",e:"🛡️",k:["Jomiy","kibr","johillik"],x:"Jomiy: insoniy fazilatli kishi kibr, manmanlik, razolat va johillikdan saqlanadi."}]},
 q:[
 {t:"m",q:"Amir Temurga otasi qanday topshiriq bergan edi?",a:["Bir suruv qo‘yni bozorda pullash","Kutubxonadan kitob olib kelish","Qo‘shni shaharga xat yetkazish","Bog‘dagi daraxtlarni sug‘orish"],e:"Samarqand bozorida qo‘ylarni sotib kelishni topshirgan."},
 {t:"m",q:"Temur ming tangaga nima sotib oldi?",a:["She’r yozilgan qog‘oz","Dastasi bezalgan qadimiy qilich","Zotdor ot","Qimmat to‘n"],e:"Qalandardan she’r yozilgan qog‘ozni oldi."},
 {t:"m",q:"Qog‘ozdagi ruboiy qaysi shoirniki edi?",a:["Kamol Xo‘jandiy","Alisher Navoiy","Kamoliddin Binoiy","Abdurahmon Jomiy"],e:"Mashhur shoir Kamol Xo‘jandiyning ruboiysi."},
 {t:"m",q:"Ruboiyning asosiy da’vati nima?",a:["Dunyoda yaxshilik bilan nom qoldirish","Kuch bilan ko‘proq yer egallash","Boylikni ehtiyotlab yashirib yurish","Uzoq mamlakatlarga sayohat qilish"],e:"Zulm bilan nom qoldirib bo‘lmaydi, yaxshilik bilan nom qoldir."},
 {t:"m",q:"Temurning otasi bu xaridga qanday baho berdi?",a:["Pul ko‘p ezgu yo‘lda sarflanibdi","Pul butunlay behuda ketibdi","Qalandar seni aldab ketibdi","Qo‘ylarni qaytarib olish kerak"],e:"Otasi bu hikmatga bir umr rioya qilishni uqtirdi."},
 {t:"m",q:"Volontyor kim?",a:["Ixtiyoriy va beg‘araz foydali ish qiluvchi shaxs","Faqat oylik maosh uchun majburan ishlovchi shaxs","Bozorda mol sotib, daromad topuvchi shaxs","Faqat o‘z oilasi yumushini bajaruvchi shaxs"],e:"Volontyor – ko‘ngilli, beminnat ijtimoiy faoliyat yurituvchi."},
 {t:"m",q:"«Volontyorlik faoliyati to‘g‘risida»gi Qonun qachon qabul qilingan?",a:["2019-yil 2-dekabrda","1991-yil 1-sentabrda","2009-yil 14-avgustda","2020-yil 9-aprelda"],e:"Darslikda shu sana ko‘rsatilgan."},
 {t:"m",q:"Jomiy fikricha, insoniy fazilatli kishi nimadan saqlanadi?",a:["Kibr va manmanlikdan","Ilm va hunardan","Mehr va oqibatdan","Sabr va qanoatdan"],e:"Kibr-havo, manmanlik, razolat, johillik illatlaridan."},
 {t:"tf",q:"Temur qog‘ozni otasining oldida o‘qishi kerak edi.",a:true,e:"Qalandar: «Buni otang oldida o‘qi!» deb tayinlagan."},
 {t:"tf",q:"Volontyor o‘z xizmati uchun albatta haq talab qiladi.",a:false,e:"Uning faoliyati ixtiyoriy, beminnat va beg‘araz."},
 {t:"tf",q:"Darslikka ko‘ra, volontyorning bir soatlik ezgu ishi kimningdir hayotini o‘zgartirishi mumkin.",a:true,e:"«Bilasizmi?» ruknida shunday deyilgan."},
 {t:"f",q:"Siz qaysi sohada volontyorlik qila olasiz va bu kimga foyda beradi?",e:"Masalan, keksalarga yordam, ekologik hashar, kichiklarga dars; faoliyat ixtiyoriy va beg‘araz bo‘lishi kerak."}]},

{id:"m24",n:"31-mavzu",t:"Bag‘rikenglik – tinchlik va totuvlik sari muhim qadam",b:5,
 map:{c:"Bag‘rikenglik",br:[
  {t:"Tushuncha",e:"🕊️",k:["tolerantlik","sabr-toqat","qabul qilish"],x:"Bag‘rikenglik – o‘zgalarning fikri, e’tiqodi va turmush tarziga sabr-toqatli bo‘lib, ularni qanday bo‘lsa shunday qabul qilish."},
  {t:"Olimjon sabog‘i",e:"🧹",k:["farrosh ayol","ism-sharif","hurmat"],x:"Ustoz farrosh ayolning ismini so‘rab, tadbirkorlik avvalo insoniylik ustiga qurilishini uqtirdi."},
  {t:"Urush yillari",e:"🚂",k:["Yuriy Stoyanov","evakuatsiya","boshpana"],x:"O‘zbek oilasi evakuatsiya qilingan rus qizchaga uy, kiyim va mehr berdi."},
  {t:"Saxiy qalb",e:"🏠",k:["7 farzand","karavot","oila topish"],x:"Yetti farzandli o‘qituvchi ayol qizchaga yagona karavotni berdi; xalq uni oilasi bilan topishtirdi."},
  {t:"Minnatdorlik",e:"🍲",k:["mehmondo‘stlik","palov","tarbiya"],x:"Stoyanov onasidagi bag‘rikenglik va mehmondo‘stlikni o‘zbek zaminidagi tarbiya natijasi deb biladi."}]},
 q:[
 {t:"m",q:"«Bag‘rikenglik» so‘zining ma’nodoshi qaysi?",a:["Tolerantlik","Kommunikativlik","Volontyorlik","Daxldorlik"],e:"Darslikda «tolerantlik» ma’nodosh sifatida berilgan."},
 {t:"m",q:"Bag‘rikenglikning mazmuni nima?",a:["O‘zgalarni qanday bo‘lsa, shundayligicha qabul qilish","Hammani o‘z fikriga majburlab ko‘ndirishga urinish","Faqat o‘ziga o‘xshagan odamlar bilan muloqot qilish","Atrofdagi barcha voqealarga mutlaqo befarq yurish"],e:"Fikr, e’tiqod va turmush tarziga sabr-toqatli bo‘lish."},
 {t:"m",q:"Olimjon universitetda qaysi fanni sevardi?",a:["«Biznes strategiyasi»","«Jahon tarixi»","«Adabiyot nazariyasi»","«Ekologiya asoslari»"],e:"Bu uning eng sevimli fani edi."},
 {t:"m",q:"Imtihonda o‘qituvchi Olimjondan nimani so‘radi?",a:["Farrosh ayolning ism-sharifini","Tadbirkorlik formulalarini","Bozordagi narxlarni","O‘z biznes rejasini"],e:"Olimjon bu ayolni har kuni ko‘rsa ham, ismini bilmasdi."},
 {t:"m",q:"Olimjon voqeasidan qanday xulosa chiqadi?",a:["Tadbirkorlik insoniylik ustiga qurilishi kerak","Tadbirkorga faqat formulalar bilimi kifoya","Rahbar xodimlar ismini bilishi shart emas","Imtihonda ko‘p gapirgan talaba yutadi"],e:"Rahbarning kuchi atrofidagilarni bilish va hurmat qilishda."},
 {t:"m",q:"Yuriy Stoyanovning onasi oilasi urush yillarida qayerga evakuatsiya qilingan?",a:["O‘zbekistonga","Qozog‘istonga","Gruziyaga","Sibirga"],e:"Stalingraddan O‘zbekistonga."},
 {t:"m",q:"Stoyanovning onasiga uyidan joy bergan ayolning kasbi nima edi?",a:["O‘qituvchi","Shifokor","Tikuvchi","Oshpaz"],e:"7 farzandli o‘qituvchi ayol joy bergan."},
 {t:"m",q:"Qizcha maktabga borishi uchun sumka nimadan tikildi?",a:["Dasturxondan","Ko‘rpadan","Gilamdan","Parda matosidan"],e:"Ko‘ylak sepga atalgan matodan, sumka dasturxondan tikilgan."},
 {t:"tf",q:"Uydagi yagona karavotda o‘qituvchi ayol yotib, qizcha yerda yotgan.",a:false,e:"Aksincha, qizcha karavotda, uy egalari yerda yotishgan."},
 {t:"tf",q:"O‘zbek xalqi Stoyanovning onasiga oilasi bilan topishishda yordam bergan.",a:true,e:"U buni eng asosiy yaxshilik sifatida eslaydi."},
 {t:"tf",q:"Voqeadan keyin Olimjon atrofidagi odamlarning kimligi va ismini bilishga e’tibor qiladigan bo‘ldi.",a:true,e:"U farrosh va haydovchini ham yaxshi biladi."},
 {t:"f",q:"Sinfingizda bag‘rikenglik qanday namoyon bo‘lishi mumkin?",e:"Boshqa millat va fikrdagi tengdoshlarni hurmat qilish, ustidan kulmaslik, tinglash va yordam berish."}]},

{id:"m25",n:"32-mavzu",t:"Daxldorlik",b:5,
 map:{c:"Daxldorlik",br:[
  {t:"Befarq bo‘lmaslik",e:"⚡",k:["uzilgan sim","1050","mas’uliyat"],x:"Bahromjon uzilib yotgan elektr simini ko‘rib, avariya xizmatiga qo‘ng‘iroq qildi."},
  {t:"Irena Sendler",e:"🚑",k:["Varshava","getto","2500 bola"],x:"Irena Sendler hayotini xavfga qo‘yib, 2500 bolani o‘limdan qutqardi."},
  {t:"Beparvolik bahosi",e:"🕷️",k:["Piter","o‘g‘ri","Ben amaki"],x:"Piter o‘g‘rini to‘xtatmadi, keyin Ben amakisi halok bo‘lganini bildi."},
  {t:"Faol fuqaro",e:"🚦",k:["svetofor","men nima qildim","murojaat"],x:"Ozodaning dadasi: «Men boshqalar uchun nima qildim» deb so‘rash kerak."},
  {t:"Beminnat yordam",e:"🧹",k:["Sulaymon","Sasha amaki","mahalla"],x:"Sulaymon sinfdoshlari bilan yolg‘iz keksa qo‘shniga yordam berdi, mahalla ham qo‘shildi."}]},
 q:[
 {t:"m",q:"Uzilib yotgan elektr simini ko‘rgan Bahromjon nima qildi?",a:["1050 avariya xizmatiga qo‘ng‘iroq qildi","Aylanib o‘tib, indamay uyiga ketdi","Simni qo‘li bilan chetga olib qo‘ydi","Yosh bolalarni tomoshaga chaqirdi"],e:"U bolalar va qariyalarni o‘ylab, xizmatga xabar berdi."},
 {t:"m",q:"Irena Sendler Varshavada kim bo‘lib ishlagan?",a:["Sanitar","O‘qituvchi","Jurnalist","Savdogar"],e:"U sanitar bo‘lib ishlagan."},
 {t:"m",q:"Irena Sendler qancha bolani o‘limdan saqlab qoldi?",a:["2500 nafar","101 nafar","250 nafar","40 nafar"],e:"6 oylikdan 15 yoshgacha bo‘lgan 2500 bola."},
 {t:"m",q:"Irena bolalar haqidagi ma’lumotlarni qayerda saqladi?",a:["Shisha idishda, do‘sti hovlisiga ko‘mib","Ishxonadagi stol tortmasida qulflab","Pochta orqali boshqa davlatga yuborib","Gazetada hammaga e’lon qilib"],e:"Urushdan keyin bolalarni oilasi bilan birlashtirishga harakat qildi."},
 {t:"m",q:"Klub boshlig‘i Piterga 3 ming o‘rniga qancha pul berdi?",a:["100 dollar","500 dollar","1000 dollar","2000 dollar"],e:"Uch daqiqa sharti bahona qilindi."},
 {t:"m",q:"Piterning beparvoligi qanday fojia bilan bog‘landi?",a:["Ben amakisi otib ketildi","Uyiga o‘t tushib ketdi","Yutuq puli yonib ketdi","Do‘sti ishidan haydaldi"],e:"Jasad uning Ben amakisi bo‘lib chiqdi."},
 {t:"m",q:"Ozodaning dadasi doim qaysi savolni berish kerakligini aytdi?",a:["«Men boshqalar uchun nima qildim?»","«Boshqalar menga nima qilib berdi?»","«Bu ishdan menga qancha foyda?»","«Nega yordamni hech kim so‘ramadi?»"],e:"Shunda hamma uchun yaxshi bo‘ladi."},
 {t:"m",q:"Sulaymon Sasha amakiga yordam uchun nima qildi?",a:["Sinfdoshlarini to‘plab, maslahat soldi","Hech kimga aytmay, yolg‘iz o‘zi tomni buzdi","Uni boshqa shaharga ko‘chirdi","Faqat chetdan kuzatib yurdi"],e:"O‘quvchilar hovli va uyni tartibga keltirdi."},
 {t:"tf",q:"Mahalla raisi Sasha amakining uyini tubdan ta’mirlashni boshlashga qaror qildi.",a:true,e:"Mahalla faollari bilan maslahatlashib shunday qilindi."},
 {t:"tf",q:"Darslikka ko‘ra, beparvo odam dushmandan kamroq xavfli.",a:false,e:"Beparvo odam dushmandan ham xavfliroq deyilgan."},
 {t:"tf",q:"Irena Sendler bolalarni qahramon bo‘lish uchun emas, insoniylik burchi sababli qutqarganini aytgan.",a:true,e:"U millati va dinidan qat’i nazar yordam berish kerakligini ta’kidlagan."},
 {t:"f",q:"Daxldorlikni o‘z hayotingizdagi misol bilan tushuntiring.",e:"Atrofdagi muammoga befarq bo‘lmay, xavfni tegishli xizmatga xabar qilish, muhtojga yordam berish, tozalik va tartibga hissa qo‘shish."}]},

{id:"m26",n:"33-mavzu",t:"Mahallamiz farovonligi – bizning farovonligimiz",b:5,
 map:{c:"Mahalla farovonligi",br:[
  {t:"Mahallani tanish",e:"🗺️",k:["manzil","aholi","millatlar"],x:"Mahallaning manzili, yer maydoni, aholisi va millat vakillari haqida ma’lumot to‘planadi."},
  {t:"Mahalla yig‘ini",e:"👥",k:["oqsoqol","xodimlar","vazifa"],x:"Mahalla oqsoqoli bilan suhbatlashib, yig‘in faoliyati va xodimlar vazifasi o‘rganiladi."},
  {t:"Muammo va yechim",e:"🛠️",k:["chiqindi","ekologiya","taklif"],x:"Chiqindi va ekologiya kabi muammolar o‘rganilib, yechim taklif qilinadi."},
  {t:"Tarix va faxr",e:"📚",k:["nomlanish","fidoyilar","o‘ziga xoslik"],x:"Mahalla tarixi, nomi, obodligiga hissa qo‘shgan insonlar va o‘ziga xosligi o‘rganiladi."},
  {t:"Tinchlik qadri",e:"🕊️",k:["osoyishtalik","Vatan","elga xizmat"],x:"Har bir yutuq zamirida tinchlik; qalbda Vatanga muhabbat, sadoqat va elga xizmat tuyg‘usi bo‘ladi."}]},
 q:[
 {t:"m",q:"Mavzudagi topshiriqni bajarish uchun kim bilan suhbat qurish kerak?",a:["Mahalla oqsoqoli bilan","Bank xodimi bilan","Teatr rejissori bilan","Chet ellik savdogar bilan"],e:"Birinchi topshiriq – mahalla oqsoqoli bilan suhbat."},
 {t:"m",q:"1-guruh mahalla haqida qaysi ma’lumotni yig‘adi?",a:["Manzili, yer maydoni va aholi soni","Faqat qadimgi afsonalar to‘plami","Boshqa davlatlarning ob-havosi","Sport jamoalarining jahon reytingi"],e:"Shuningdek, millat vakillari haqida ham."},
 {t:"m",q:"Mahalla muammosiga misol sifatida darslikda nima keltirilgan?",a:["Chiqindi tashlash va ekologiya","Kosmik kemalar yetishmasligi","Dengiz portining yo‘qligi","Tog‘ cho‘qqilarining balandligi"],e:"Chiqindi tashlash va ekologiya bilan bog‘liq muammolar."},
 {t:"m",q:"Muammoni o‘rgangandan keyin nima qilish so‘raladi?",a:["Hal qilish yechimini taklif etish","Uni boshqalardan sir tutish","Aybdorni topib, urishib kelish","Mavzuni darhol yopib qo‘yish"],e:"«Muammoni hal qilish yechimini taklif qiling»."},
 {t:"m",q:"Mahalla tarixini o‘rganishda 2-guruh nimaga e’tibor beradi?",a:["Mahallaning nomlanishiga","Jahon valyuta kurslariga","Samolyot qatnovi jadvaliga","Okean chuqurligi o‘lchoviga"],e:"Tarix va nomlanish haqida ma’lumot to‘planadi."},
 {t:"m",q:"2-guruh qaysi insonlar haqida o‘rganadi?",a:["Mahalla obodligiga hissa qo‘shganlar","Faqat chet elda yashovchi aktyorlar","Boshqa shaharlik mashhur savdogarlar","Mahallaga hech kelmagan sayyohlar"],e:"Mahalla rivoji uchun mehnat qilgan va qilayotgan insonlar."},
 {t:"m",q:"Mavzudagi hikmatga ko‘ra, har bir yutug‘imiz zamirida nima mujassam?",a:["Tinchlik-osoyishtalik","Kutilmagan tasodifiy omad","Katta sarmoya","O‘zaro raqobat"],e:"Har bir yutuq zamirida tinchlik-osoyishtalik bor."},
 {t:"m",q:"Inson qalbida mudom qaysi tuyg‘u jo‘sh uradi, deyilgan?",a:["Vatanga muhabbat va elga xizmat","Boylikka ruju va shuhratparastlik","Yolg‘izlik va hammadan uzoqlashish","Sayohat zavqi va o‘yin ishtiyoqi"],e:"Ona Vatanga muhabbat, yurtga sadoqat va elga xizmat."},
 {t:"tf",q:"Topshiriqda o‘quvchi o‘zini mahalla oqsoqoli deb tasavvur qilib, farovonlik uchun taklif yozadi.",a:true,e:"Ikkinchi topshiriq aynan shunday."},
 {t:"tf",q:"Mahalla yig‘inida kimlar ishlashi va vazifalarini o‘rganish topshiriqqa kirmaydi.",a:false,e:"1-guruh yig‘in faoliyati, xodimlari va vazifalarini o‘rganadi."},
 {t:"tf",q:"Hikmatda dunyodagi voqealarga teran nazar solib, to‘g‘ri xulosa chiqarish kerakligi aytiladi.",a:true,e:"Bu tinchlik qadrini anglab yetishga yordam beradi."},
 {t:"f",q:"Mahalla oqsoqoli bo‘lsangiz, mahallangiz farovonligi uchun qanday takliflar kiritardingiz?",e:"Tozalik va ko‘kalamzorlashtirish, hashar, chiqindi muammosini hal etish, yolg‘iz keksalarga yordam, yoshlar uchun to‘garaklar."}]}
);
